-- =====================================================================
-- SCHOOL-HUB — ALL MIGRATIONS IN ONE FILE
--
-- Generated from supabase/migrations/ — do not edit this file by hand.
-- Regenerate with: npm run sql:bundle
--
-- Paste the whole thing into the Supabase SQL editor and press Run, once.
-- Same statements as the numbered files, same order, wrapped in one
-- transaction so a failure leaves nothing half-applied.
--
-- Files included: 0001_extensions.sql, 0002_core_tables.sql, 0003_functions.sql, 0004_rls.sql, 0005_storage.sql, 0006_lesson_no_homework.sql, 0007_privilege_hardening.sql, 0008_sibling_identity_scope.sql, 0009_realtime_notifications.sql, 0010_helper_role.sql, 0011_notify_parent_on_helper_review.sql, 0012_child_assignment_insert.sql
-- =====================================================================

begin;

-- ---------------------------------------------------------------------
-- 0001_extensions.sql
-- ---------------------------------------------------------------------
-- =============================================================================
-- SCHOOL-HUB — 0001_extensions.sql
-- Extensions and shared utility functions.
-- Safe to run more than once. Runs in the Supabase SQL editor as-is.
-- =============================================================================

create schema if not exists extensions;

-- pgcrypto: bcrypt (crypt/gen_salt) for seeded auth users and child PIN hashes.
-- On Supabase this extension already lives in the "extensions" schema.
create extension if not exists pgcrypto with schema extensions;

-- gen_random_uuid() is core in Postgres 13+, no extension needed.

-- -----------------------------------------------------------------------------
-- Generic updated_at maintenance trigger.
-- Attached in 0002 to every table that has an updated_at column.
-- -----------------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

comment on function public.set_updated_at() is
  'BEFORE UPDATE trigger: stamps updated_at with now().';

-- -----------------------------------------------------------------------------
-- Non-throwing text -> uuid cast. Used by the storage path helper in 0005,
-- where object names are arbitrary user-supplied strings.
-- -----------------------------------------------------------------------------
create or replace function public.try_uuid(p_text text)
returns uuid
language plpgsql
immutable
as $$
begin
  return p_text::uuid;
exception
  when others then
    return null;
end;
$$;

comment on function public.try_uuid(text) is
  'Casts text to uuid, returning null instead of raising on malformed input.';

grant execute on function public.try_uuid(text) to authenticated, anon, service_role;

-- ---------------------------------------------------------------------
-- 0002_core_tables.sql
-- ---------------------------------------------------------------------
-- =============================================================================
-- SCHOOL-HUB — 0002_core_tables.sql
-- All application tables, constraints, indexes, updated_at triggers and the
-- auth.users -> public.profiles bridge.
-- Depends on: 0001_extensions.sql
-- =============================================================================

-- =============================================================================
-- profiles
-- One row per auth user (parent, child or helper).
-- =============================================================================
create table if not exists public.profiles (
  id            uuid        primary key references auth.users (id) on delete cascade,
  role          text        not null default 'parent'
                            check (role in ('parent', 'child', 'helper')),
  display_name  text,
  avatar_url    text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

comment on table public.profiles is 'Application profile for every auth.users row.';

-- =============================================================================
-- families
-- =============================================================================
create table if not exists public.families (
  id          uuid        primary key default gen_random_uuid(),
  name        text        not null check (length(btrim(name)) > 0),
  owner_id    uuid        not null references public.profiles (id) on delete cascade,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create index if not exists idx_families_owner_id on public.families (owner_id);

-- =============================================================================
-- family_members
-- Membership + per-member permissions. permissions jsonb shape (phase 2 helper):
--   { "can_review": true, "children": ["<child uuid>", ...] }
-- "children": null / absent  => all children in the family.
-- =============================================================================
create table if not exists public.family_members (
  id           uuid        primary key default gen_random_uuid(),
  family_id    uuid        not null references public.families (id) on delete cascade,
  user_id      uuid        not null references public.profiles (id) on delete cascade,
  role         text        not null check (role in ('parent', 'child', 'helper')),
  permissions  jsonb       not null default '{}'::jsonb,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  constraint family_members_unique unique (family_id, user_id)
);

create index if not exists idx_family_members_user_id on public.family_members (user_id);
create index if not exists idx_family_members_family_id on public.family_members (family_id);

-- =============================================================================
-- children
-- profile_id is the child's OWN auth user; null until the invite code is redeemed.
-- =============================================================================
create table if not exists public.children (
  id                uuid        primary key default gen_random_uuid(),
  family_id         uuid        not null references public.families (id) on delete cascade,
  profile_id        uuid        unique references public.profiles (id) on delete set null,
  name              text        not null check (length(btrim(name)) > 0),
  grade             int         check (grade between 1 and 12),
  school            text,
  birth_date        date,
  avatar_url        text,
  color             text        not null default '#4f46e5',
  is_active         boolean     not null default true,

  -- invite / PIN login (see SPEC section 1)
  invite_code       text        unique
                                check (invite_code is null
                                       or length(invite_code) between 4 and 12),
  invite_expires_at timestamptz,
  pin_hash          text,
  pin_attempts      int         not null default 0 check (pin_attempts >= 0),
  pin_locked_until  timestamptz,

  -- per-child UI preferences, set by the parent
  ui_mode           text        not null default 'full'
                                check (ui_mode in ('simple', 'full')),
  show_own_stats    boolean     not null default false,

  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

create index if not exists idx_children_family_id on public.children (family_id);
create index if not exists idx_children_profile_id on public.children (profile_id);
create index if not exists idx_children_invite_code on public.children (invite_code)
  where invite_code is not null;

comment on column public.children.show_own_stats is
  'Parent-controlled: may the child see their own statistics/progress. Default off.';
comment on column public.children.ui_mode is
  'simple = oversized, reduced kid UI; full = normal kid UI.';

-- =============================================================================
-- subjects
-- =============================================================================
create table if not exists public.subjects (
  id            uuid        primary key default gen_random_uuid(),
  child_id      uuid        not null references public.children (id) on delete cascade,
  name          text        not null check (length(btrim(name)) > 0),
  color         text        not null default '#64748b',
  teacher_name  text,
  sort_order    int         not null default 0,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint subjects_child_name_unique unique (child_id, name)
);

create index if not exists idx_subjects_child_id on public.subjects (child_id, sort_order);

-- =============================================================================
-- schedule_slots
-- weekday: 1 = Monday ... 7 = Sunday (ISO 8601 / extract(isodow)).
-- =============================================================================
create table if not exists public.schedule_slots (
  id              uuid        primary key default gen_random_uuid(),
  child_id        uuid        not null references public.children (id) on delete cascade,
  subject_id      uuid        not null references public.subjects (id) on delete cascade,
  weekday         int         not null check (weekday between 1 and 7),
  start_time      time        not null,
  end_time        time        not null,
  effective_from  date        not null default current_date,
  effective_to    date,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint schedule_slots_time_order check (end_time > start_time),
  constraint schedule_slots_date_order check (effective_to is null
                                              or effective_to >= effective_from)
);

create index if not exists idx_schedule_slots_child_weekday
  on public.schedule_slots (child_id, weekday, start_time);
create index if not exists idx_schedule_slots_subject_id
  on public.schedule_slots (subject_id);

-- =============================================================================
-- lessons  -- "what we covered" on a given day
-- =============================================================================
create table if not exists public.lessons (
  id          uuid        primary key default gen_random_uuid(),
  child_id    uuid        not null references public.children (id) on delete cascade,
  subject_id  uuid        references public.subjects (id) on delete set null,
  date        date        not null default current_date,
  topic       text,
  notes       text,
  slot_id     uuid        references public.schedule_slots (id) on delete set null,
  created_by  uuid        references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- SPEC index: lessons(child_id, date)
create index if not exists idx_lessons_child_date on public.lessons (child_id, date desc);
create index if not exists idx_lessons_subject_id on public.lessons (subject_id);
create index if not exists idx_lessons_slot_id on public.lessons (slot_id);

-- =============================================================================
-- topics  (self-referencing tree under a subject)
-- =============================================================================
create table if not exists public.topics (
  id              uuid        primary key default gen_random_uuid(),
  subject_id      uuid        not null references public.subjects (id) on delete cascade,
  name            text        not null check (length(btrim(name)) > 0),
  parent_topic_id uuid        references public.topics (id) on delete cascade,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint topics_not_self_parent check (parent_topic_id is null or parent_topic_id <> id)
);

create index if not exists idx_topics_subject_id on public.topics (subject_id);
create index if not exists idx_topics_parent_topic_id on public.topics (parent_topic_id);

-- =============================================================================
-- assignments
-- status machine enforced by the trigger in 0003_functions.sql.
-- priority: 1 = low, 2 = normal, 3 = high.
-- =============================================================================
create table if not exists public.assignments (
  id              uuid        primary key default gen_random_uuid(),
  lesson_id       uuid        references public.lessons (id) on delete set null,
  child_id        uuid        not null references public.children (id) on delete cascade,
  subject_id      uuid        references public.subjects (id) on delete set null,
  topic_id        uuid        references public.topics (id) on delete set null,

  title           text        not null check (length(btrim(title)) > 0),
  description     text,
  source_ref      text,                       -- "წიგნი გვ. 45, სავარჯიშო 3"

  due_date        date,
  due_time        time,

  status          text        not null default 'assigned'
                              check (status in ('assigned', 'in_progress',
                                                'submitted', 'approved', 'redo')),
  priority        int         not null default 2 check (priority between 1 and 3),

  self_rating     int         check (self_rating between 1 and 5),
  difficulty_note text,
  minutes_spent   int         check (minutes_spent >= 0),
  redo_count      int         not null default 0 check (redo_count >= 0),

  submitted_at    timestamptz,
  reviewed_at     timestamptz,
  reviewed_by     uuid        references public.profiles (id) on delete set null,
  review_comment  text,

  ai_check        jsonb,                      -- phase 3

  created_by      uuid        references public.profiles (id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

-- SPEC indexes
create index if not exists idx_assignments_child_status
  on public.assignments (child_id, status);
create index if not exists idx_assignments_child_due_date
  on public.assignments (child_id, due_date);
-- supporting indexes
create index if not exists idx_assignments_lesson_id on public.assignments (lesson_id);
create index if not exists idx_assignments_subject_id on public.assignments (subject_id);
create index if not exists idx_assignments_topic_id on public.assignments (topic_id);
create index if not exists idx_assignments_status_submitted_at
  on public.assignments (status, submitted_at desc);

-- =============================================================================
-- assignment_events  -- append-only audit trail, written by the status trigger
-- =============================================================================
create table if not exists public.assignment_events (
  id            uuid        primary key default gen_random_uuid(),
  assignment_id uuid        not null references public.assignments (id) on delete cascade,
  actor_id      uuid        references public.profiles (id) on delete set null,
  from_status   text        check (from_status in ('assigned', 'in_progress',
                                                   'submitted', 'approved', 'redo')),
  to_status     text        not null
                            check (to_status in ('assigned', 'in_progress',
                                                 'submitted', 'approved', 'redo')),
  comment       text,
  created_at    timestamptz not null default now()
);

create index if not exists idx_assignment_events_assignment
  on public.assignment_events (assignment_id, created_at desc);

comment on table public.assignment_events is
  'Append-only. Rows are inserted only by public.assignments_status_guard() / _log_insert().';

-- =============================================================================
-- messages
-- child_id is denormalised from the parent assignment/lesson so that RLS on
-- messages (and attachments) stays a single-column comparison. Maintained by a
-- BEFORE INSERT trigger; see public.resolve_message_child_id().
-- =============================================================================
create table if not exists public.messages (
  id            uuid        primary key default gen_random_uuid(),
  assignment_id uuid        references public.assignments (id) on delete cascade,
  lesson_id     uuid        references public.lessons (id) on delete cascade,
  child_id      uuid        not null references public.children (id) on delete cascade,
  author_id     uuid        references public.profiles (id) on delete set null,
  body          text,
  voice_path    text,
  created_at    timestamptz not null default now(),
  edited_at     timestamptz,
  constraint messages_one_parent check (num_nonnulls(assignment_id, lesson_id) = 1),
  constraint messages_has_content check (num_nonnulls(body, voice_path) >= 1)
);

-- SPEC index: messages(assignment_id, created_at)
create index if not exists idx_messages_assignment_created
  on public.messages (assignment_id, created_at);
create index if not exists idx_messages_lesson_created
  on public.messages (lesson_id, created_at);
create index if not exists idx_messages_child_id on public.messages (child_id);
create index if not exists idx_messages_author_id on public.messages (author_id);

-- =============================================================================
-- message_reads
-- =============================================================================
create table if not exists public.message_reads (
  message_id  uuid        not null references public.messages (id) on delete cascade,
  user_id     uuid        not null references public.profiles (id) on delete cascade,
  read_at     timestamptz not null default now(),
  primary key (message_id, user_id)
);

create index if not exists idx_message_reads_user_id on public.message_reads (user_id);

-- =============================================================================
-- attachments
-- child_id denormalised for the same reason as messages.
-- storage_path is the object name inside the private "evidence" bucket:
--   {child_id}/{assignment_id}/{uuid}.webp
-- =============================================================================
create table if not exists public.attachments (
  id            uuid        primary key default gen_random_uuid(),
  assignment_id uuid        references public.assignments (id) on delete cascade,
  lesson_id     uuid        references public.lessons (id) on delete cascade,
  message_id    uuid        references public.messages (id) on delete cascade,
  child_id      uuid        not null references public.children (id) on delete cascade,
  kind          text        not null
                            check (kind in ('task_source', 'solution', 'review', 'chat')),
  storage_path  text        not null unique,
  thumb_path    text,
  mime          text        not null default 'image/webp',
  size_bytes    bigint      check (size_bytes is null or size_bytes >= 0),
  width         int         check (width is null or width > 0),
  height        int         check (height is null or height > 0),
  sort_order    int         not null default 0,
  uploaded_by   uuid        references public.profiles (id) on delete set null,
  created_at    timestamptz not null default now(),
  constraint attachments_has_owner_row
    check (num_nonnulls(assignment_id, lesson_id, message_id) >= 1)
);

-- SPEC index: attachments(assignment_id, kind)
create index if not exists idx_attachments_assignment_kind
  on public.attachments (assignment_id, kind, sort_order);
create index if not exists idx_attachments_lesson_id on public.attachments (lesson_id);
create index if not exists idx_attachments_message_id on public.attachments (message_id);
create index if not exists idx_attachments_child_id on public.attachments (child_id);

-- =============================================================================
-- grades  -- parent-only data (children must never be able to select this)
-- =============================================================================
create table if not exists public.grades (
  id            uuid        primary key default gen_random_uuid(),
  child_id      uuid        not null references public.children (id) on delete cascade,
  subject_id    uuid        references public.subjects (id) on delete set null,
  date          date        not null default current_date,
  value         numeric(5,2) not null check (value >= 0),
  max_value     numeric(5,2) not null default 10 check (max_value > 0),
  source        text        not null default 'teacher'
                            check (source in ('teacher', 'internal')),
  note          text,
  attachment_id uuid        references public.attachments (id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint grades_value_within_max check (value <= max_value)
);

create index if not exists idx_grades_child_date on public.grades (child_id, date desc);
create index if not exists idx_grades_subject_id on public.grades (subject_id);
create index if not exists idx_grades_attachment_id on public.grades (attachment_id);

-- =============================================================================
-- topic_mastery  -- phase 2
-- =============================================================================
create table if not exists public.topic_mastery (
  id         uuid        primary key default gen_random_uuid(),
  child_id   uuid        not null references public.children (id) on delete cascade,
  topic_id   uuid        not null references public.topics (id) on delete cascade,
  level      int         not null default 0 check (level between 0 and 100),
  samples    int         not null default 0 check (samples >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint topic_mastery_unique unique (child_id, topic_id)
);

create index if not exists idx_topic_mastery_child_id on public.topic_mastery (child_id);
create index if not exists idx_topic_mastery_topic_id on public.topic_mastery (topic_id);

-- =============================================================================
-- notifications  -- phase 2
-- =============================================================================
create table if not exists public.notifications (
  id         uuid        primary key default gen_random_uuid(),
  user_id    uuid        not null references public.profiles (id) on delete cascade,
  type       text        not null,
  payload    jsonb       not null default '{}'::jsonb,
  read_at    timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists idx_notifications_user_unread
  on public.notifications (user_id, created_at desc) where read_at is null;

-- =============================================================================
-- updated_at triggers
-- =============================================================================
do $$
declare
  t text;
  tables text[] := array[
    'profiles', 'families', 'family_members', 'children', 'subjects',
    'schedule_slots', 'lessons', 'topics', 'assignments', 'grades', 'topic_mastery'
  ];
begin
  foreach t in array tables loop
    execute format('drop trigger if exists trg_%1$s_updated_at on public.%1$I', t);
    execute format(
      'create trigger trg_%1$s_updated_at before update on public.%1$I
         for each row execute function public.set_updated_at()', t);
  end loop;
end;
$$;

-- =============================================================================
-- auth.users -> public.profiles bridge
-- Runs as the definer so it can write to profiles regardless of RLS.
-- raw_user_meta_data may carry { "role": "...", "display_name": "..." }.
-- =============================================================================
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_role text;
begin
  v_role := coalesce(new.raw_user_meta_data ->> 'role', 'parent');
  if v_role not in ('parent', 'child', 'helper') then
    v_role := 'parent';
  end if;

  insert into public.profiles (id, role, display_name, avatar_url)
  values (
    new.id,
    v_role,
    coalesce(
      nullif(btrim(new.raw_user_meta_data ->> 'display_name'), ''),
      nullif(split_part(coalesce(new.email, ''), '@', 1), ''),
      'user'
    ),
    new.raw_user_meta_data ->> 'avatar_url'
  )
  on conflict (id) do nothing;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- =============================================================================
-- Backfill profiles for auth users that predate this migration.
-- =============================================================================
insert into public.profiles (id, role, display_name)
select u.id,
       'parent',
       coalesce(nullif(split_part(coalesce(u.email, ''), '@', 1), ''), 'user')
from auth.users u
left join public.profiles p on p.id = u.id
where p.id is null;

-- ---------------------------------------------------------------------
-- 0003_functions.sql
-- ---------------------------------------------------------------------
-- =============================================================================
-- SCHOOL-HUB — 0003_functions.sql
-- Authorisation helpers (used by the RLS policies in 0004) and the assignment
-- status machine.
-- Depends on: 0002_core_tables.sql
--
-- Every helper is SECURITY DEFINER + STABLE so that a policy on table X can look
-- up table Y without triggering Y's own RLS (and without recursive policies).
-- They take no user input other than an id, and each one pins search_path.
-- =============================================================================

-- =============================================================================
-- 1. Identity helpers
-- =============================================================================

-- The family the current user belongs to.
-- Order of preference: explicit membership -> child record -> family ownership.
create or replace function public.current_family_id()
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(
    (select fm.family_id
       from public.family_members fm
      where fm.user_id = auth.uid()
      order by case fm.role when 'parent' then 0 when 'child' then 1 else 2 end,
               fm.created_at
      limit 1),
    (select c.family_id
       from public.children c
      where c.profile_id = auth.uid()
      limit 1),
    (select f.id
       from public.families f
      where f.owner_id = auth.uid()
      limit 1)
  );
$$;

comment on function public.current_family_id() is
  'Family id of the calling user (membership, child record or ownership).';

-- Is the caller a parent? (profile role is the source of truth)
create or replace function public.is_parent()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.profiles p
     where p.id = auth.uid() and p.role = 'parent'
  );
$$;

create or replace function public.is_helper()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.profiles p
     where p.id = auth.uid() and p.role = 'helper'
  );
$$;

-- The children row that IS the caller (null for parents/helpers).
create or replace function public.my_child_id()
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select c.id
    from public.children c
   where c.profile_id = auth.uid()
   limit 1;
$$;

create or replace function public.is_child()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select public.my_child_id() is not null;
$$;

-- All children in the caller's family.
create or replace function public.my_family_child_ids()
returns setof uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select c.id
    from public.children c
   where c.family_id = public.current_family_id();
$$;

-- All users in the caller's family (including the owner).
create or replace function public.my_family_user_ids()
returns setof uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select fm.user_id
    from public.family_members fm
   where fm.family_id = public.current_family_id()
  union
  select f.owner_id
    from public.families f
   where f.id = public.current_family_id()
  union
  select c.profile_id
    from public.children c
   where c.family_id = public.current_family_id()
     and c.profile_id is not null;
$$;

create or replace function public.child_in_my_family(p_child_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.children c
     where c.id = p_child_id
       and c.family_id = public.current_family_id()
  );
$$;

-- Does the child let a logged-in child see their own statistics?
create or replace function public.child_stats_visible(p_child_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.children c
     where c.id = p_child_id and c.show_own_stats
  );
$$;

-- =============================================================================
-- 2. Lookup helpers for tables that do not carry child_id directly
-- =============================================================================

create or replace function public.assignment_child_id(p_assignment_id uuid)
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select a.child_id from public.assignments a where a.id = p_assignment_id;
$$;

create or replace function public.lesson_child_id(p_lesson_id uuid)
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select l.child_id from public.lessons l where l.id = p_lesson_id;
$$;

create or replace function public.message_child_id(p_message_id uuid)
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select m.child_id from public.messages m where m.id = p_message_id;
$$;

create or replace function public.subject_child_id(p_subject_id uuid)
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select s.child_id from public.subjects s where s.id = p_subject_id;
$$;

create or replace function public.topic_child_id(p_topic_id uuid)
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select s.child_id
    from public.topics t
    join public.subjects s on s.id = t.subject_id
   where t.id = p_topic_id;
$$;

-- =============================================================================
-- 3. Review authority
-- A parent of the family, or (phase 2) a helper whose permissions grant review
-- rights for this child.
-- =============================================================================
create or replace function public.can_review(p_child_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
      from public.children c
      join public.families f on f.id = c.family_id
     where c.id = p_child_id
       and f.owner_id = auth.uid()
  )
  or exists (
    select 1
      from public.children c
      join public.family_members fm on fm.family_id = c.family_id
     where c.id = p_child_id
       and fm.user_id = auth.uid()
       and (
         fm.role = 'parent'
         or (
           fm.role = 'helper'
           and lower(coalesce(fm.permissions ->> 'can_review', 'false'))
               in ('true', 't', '1', 'yes')
           and (
             jsonb_typeof(fm.permissions -> 'children') is distinct from 'array'
             or (fm.permissions -> 'children') ? (p_child_id::text)
           )
         )
       )
  );
$$;

comment on function public.can_review(uuid) is
  'True when the caller may approve/return work for this child (parent, family owner, or helper with can_review).';

-- =============================================================================
-- 4. Grants
-- =============================================================================
do $$
declare
  fn text;
  fns text[] := array[
    'public.current_family_id()',
    'public.is_parent()',
    'public.is_helper()',
    'public.is_child()',
    'public.my_child_id()',
    'public.my_family_child_ids()',
    'public.my_family_user_ids()',
    'public.child_in_my_family(uuid)',
    'public.child_stats_visible(uuid)',
    'public.assignment_child_id(uuid)',
    'public.lesson_child_id(uuid)',
    'public.message_child_id(uuid)',
    'public.subject_child_id(uuid)',
    'public.topic_child_id(uuid)',
    'public.can_review(uuid)'
  ];
begin
  foreach fn in array fns loop
    execute format('revoke all on function %s from public', fn);
    execute format('grant execute on function %s to authenticated, service_role', fn);
  end loop;
end;
$$;

-- =============================================================================
-- 5. child_id backfill for messages and attachments
-- Lets RLS on those tables be a single-column comparison.
-- =============================================================================
create or replace function public.resolve_message_child_id()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if new.child_id is null then
    new.child_id := coalesce(
      (select a.child_id from public.assignments a where a.id = new.assignment_id),
      (select l.child_id from public.lessons l where l.id = new.lesson_id)
    );
  end if;

  if new.child_id is null then
    raise exception 'messages.child_id could not be resolved from assignment_id/lesson_id'
      using errcode = '23502';
  end if;

  if new.author_id is null then
    new.author_id := auth.uid();
  end if;

  return new;
end;
$$;

drop trigger if exists trg_messages_resolve_child on public.messages;
create trigger trg_messages_resolve_child
  before insert on public.messages
  for each row execute function public.resolve_message_child_id();

create or replace function public.resolve_attachment_child_id()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if new.child_id is null then
    new.child_id := coalesce(
      (select a.child_id from public.assignments a where a.id = new.assignment_id),
      (select l.child_id from public.lessons   l where l.id = new.lesson_id),
      (select m.child_id from public.messages  m where m.id = new.message_id)
    );
  end if;

  if new.child_id is null then
    raise exception 'attachments.child_id could not be resolved from assignment_id/lesson_id/message_id'
      using errcode = '23502';
  end if;

  if new.uploaded_by is null then
    new.uploaded_by := auth.uid();
  end if;

  return new;
end;
$$;

drop trigger if exists trg_attachments_resolve_child on public.attachments;
create trigger trg_attachments_resolve_child
  before insert on public.attachments
  for each row execute function public.resolve_attachment_child_id();

-- =============================================================================
-- 6. Assignment status machine
--
-- Allowed transitions
--   assigned    -> in_progress
--   assigned    -> submitted
--   in_progress -> submitted
--   submitted   -> approved      (reviewer only)
--   submitted   -> redo          (reviewer only)
--   redo        -> in_progress   (redo_count += 1)
--   approved    -> redo          (reviewer only, correction)
--   approved    -> in_progress   (reviewer only, correction)
--
-- Side effects
--   -> submitted            : submitted_at = now()
--   -> approved | redo      : reviewed_at = now(), reviewed_by = auth.uid()
--   redo -> in_progress     : redo_count = redo_count + 1
--   any status change       : one row appended to assignment_events
--
-- Column lockdown: a child may never change review_comment, reviewed_by,
-- reviewed_at, redo_count, child_id.
--
-- Service context (auth.uid() is null: service_role key, SQL editor, seed) is
-- treated as privileged so migrations and admin scripts are not blocked.
-- =============================================================================
create or replace function public.assignments_status_guard()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid           uuid    := auth.uid();
  v_service       boolean := (auth.uid() is null);
  v_child_profile uuid;
  v_is_child      boolean;
  v_can_review    boolean;
  v_transition    text;
  v_comment       text;
begin
  select c.profile_id into v_child_profile
    from public.children c
   where c.id = new.child_id;

  v_is_child   := (v_uid is not null and v_uid is not distinct from v_child_profile);
  v_can_review := (not v_service) and public.can_review(new.child_id);

  -- ---------------------------------------------------------------- ownership
  if new.child_id is distinct from old.child_id and not v_service then
    raise exception 'assignments.child_id cannot be changed'
      using errcode = '42501';
  end if;

  -- ------------------------------------------------------- child column lock
  if v_is_child and not v_can_review then
    if new.review_comment is distinct from old.review_comment then
      raise exception 'A child may not change review_comment' using errcode = '42501';
    end if;
    if new.reviewed_by is distinct from old.reviewed_by then
      raise exception 'A child may not change reviewed_by' using errcode = '42501';
    end if;
    if new.reviewed_at is distinct from old.reviewed_at then
      raise exception 'A child may not change reviewed_at' using errcode = '42501';
    end if;
    if new.redo_count is distinct from old.redo_count then
      raise exception 'A child may not change redo_count' using errcode = '42501';
    end if;
  end if;

  -- -------------------------------------------------------------- transition
  if new.status is not distinct from old.status then
    return new;
  end if;

  v_transition := old.status || '->' || new.status;

  if v_transition not in (
       'assigned->in_progress',
       'assigned->submitted',
       'in_progress->submitted',
       'submitted->approved',
       'submitted->redo',
       'redo->in_progress',
       'approved->redo',
       'approved->in_progress'
     ) then
    raise exception 'Illegal assignment status transition: % -> %', old.status, new.status
      using errcode = '23514';
  end if;

  -- corrections out of an already approved assignment are reviewer-only
  if old.status = 'approved' and not (v_can_review or v_service) then
    raise exception 'Only a parent (or a helper with review rights) may reopen an approved assignment'
      using errcode = '42501';
  end if;

  -- approve / return for redo are reviewer-only
  if new.status in ('approved', 'redo') then
    if not (v_can_review or v_service) then
      raise exception 'Only a parent (or a helper with review rights) may set status to %', new.status
        using errcode = '42501';
    end if;
    new.reviewed_at := now();
    new.reviewed_by := v_uid;
  end if;

  if new.status = 'submitted' then
    new.submitted_at := now();
  end if;

  if old.status = 'redo' and new.status = 'in_progress' then
    new.redo_count := coalesce(old.redo_count, 0) + 1;
  end if;

  -- ------------------------------------------------------------------ audit
  -- On a review decision always record the comment that was in force, even when it
  -- repeats the previous one. Returning the same work twice with the same wording is
  -- exactly the case the audit trail exists to show; de-duplicating it would hide
  -- the second rejection.
  v_comment := case
                 when new.status in ('approved', 'redo')
                   then new.review_comment
                 when new.review_comment is distinct from old.review_comment
                   then new.review_comment
                 else null
               end;

  insert into public.assignment_events
    (assignment_id, actor_id, from_status, to_status, comment)
  values
    (new.id, v_uid, old.status, new.status, v_comment);

  return new;
end;
$$;

drop trigger if exists trg_assignments_status_guard on public.assignments;
create trigger trg_assignments_status_guard
  before update on public.assignments
  for each row execute function public.assignments_status_guard();

-- Log the initial status so the audit trail starts at row creation.
create or replace function public.assignments_log_insert()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.assignment_events
    (assignment_id, actor_id, from_status, to_status, comment)
  values
    (new.id, coalesce(auth.uid(), new.created_by), null, new.status, null);
  return new;
end;
$$;

drop trigger if exists trg_assignments_log_insert on public.assignments;
create trigger trg_assignments_log_insert
  after insert on public.assignments
  for each row execute function public.assignments_log_insert();

-- ---------------------------------------------------------------------
-- 0004_rls.sql
-- ---------------------------------------------------------------------
-- =============================================================================
-- SCHOOL-HUB — 0004_rls.sql
-- Row Level Security. RLS is enabled on EVERY table in the public schema.
-- Depends on: 0003_functions.sql
--
-- Roles
--   parent  : full access to everything under their own family_id
--   child   : row scope limited to their own children.id; SELECT/INSERT/UPDATE
--             only, never DELETE, never grades, never a sibling's rows.
--             Column-level limits on assignments are enforced by the trigger
--             public.assignments_status_guard() (0003), because policies cannot
--             express "these columns may not change".
--   helper  : phase 2 scaffold — SELECT + INSERT on messages only.
--
-- anon has no policies anywhere, so unauthenticated requests see nothing.
-- service_role bypasses RLS (used by server actions that must act as admin:
-- creating child auth users, redeeming invite codes, verifying PINs).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Enable RLS everywhere
-- -----------------------------------------------------------------------------
do $$
declare
  t text;
  tables text[] := array[
    'profiles', 'families', 'family_members', 'children', 'subjects',
    'schedule_slots', 'lessons', 'topics', 'assignments', 'assignment_events',
    'messages', 'message_reads', 'attachments', 'grades', 'topic_mastery',
    'notifications'
  ];
begin
  foreach t in array tables loop
    execute format('alter table public.%I enable row level security', t);
  end loop;
end;
$$;

-- Baseline privileges (RLS still decides which rows are visible).
do $$
declare
  t text;
  tables text[] := array[
    'profiles', 'families', 'family_members', 'children', 'subjects',
    'schedule_slots', 'lessons', 'topics', 'assignments', 'assignment_events',
    'messages', 'message_reads', 'attachments', 'grades', 'topic_mastery',
    'notifications'
  ];
begin
  foreach t in array tables loop
    execute format(
      'grant select, insert, update, delete on public.%I to authenticated', t);
    execute format('revoke all on public.%I from anon', t);
  end loop;
end;
$$;

-- =============================================================================
-- profiles
-- =============================================================================
drop policy if exists profiles_select_self_or_family on public.profiles;
create policy profiles_select_self_or_family on public.profiles
  for select to authenticated
  using (
    id = auth.uid()
    or id in (select public.my_family_user_ids())
  );

drop policy if exists profiles_update_self on public.profiles;
create policy profiles_update_self on public.profiles
  for update to authenticated
  using (id = auth.uid())
  with check (id = auth.uid());

-- No INSERT/DELETE policies: profiles are created by the auth.users trigger
-- (public.handle_new_user) and removed by the cascade from auth.users.

-- =============================================================================
-- families
-- =============================================================================
drop policy if exists families_select_member on public.families;
create policy families_select_member on public.families
  for select to authenticated
  using (id = public.current_family_id() or owner_id = auth.uid());

drop policy if exists families_insert_parent on public.families;
create policy families_insert_parent on public.families
  for insert to authenticated
  with check (public.is_parent() and owner_id = auth.uid());

drop policy if exists families_update_owner on public.families;
create policy families_update_owner on public.families
  for update to authenticated
  using (public.is_parent() and owner_id = auth.uid())
  with check (public.is_parent() and owner_id = auth.uid());

drop policy if exists families_delete_owner on public.families;
create policy families_delete_owner on public.families
  for delete to authenticated
  using (owner_id = auth.uid());

-- =============================================================================
-- family_members
-- =============================================================================
drop policy if exists family_members_select on public.family_members;
create policy family_members_select on public.family_members
  for select to authenticated
  using (family_id = public.current_family_id() or user_id = auth.uid());

drop policy if exists family_members_insert_parent on public.family_members;
create policy family_members_insert_parent on public.family_members
  for insert to authenticated
  with check (
    public.is_parent()
    and family_id in (select f.id from public.families f where f.owner_id = auth.uid())
  );

drop policy if exists family_members_update_parent on public.family_members;
create policy family_members_update_parent on public.family_members
  for update to authenticated
  using (
    public.is_parent()
    and family_id in (select f.id from public.families f where f.owner_id = auth.uid())
  )
  with check (
    public.is_parent()
    and family_id in (select f.id from public.families f where f.owner_id = auth.uid())
  );

drop policy if exists family_members_delete_parent on public.family_members;
create policy family_members_delete_parent on public.family_members
  for delete to authenticated
  using (
    public.is_parent()
    and family_id in (select f.id from public.families f where f.owner_id = auth.uid())
  );

-- =============================================================================
-- children
-- The child may READ their own row only. invite_code / pin_hash / ui_mode /
-- show_own_stats are parent-controlled, so the child gets no UPDATE policy;
-- PIN setup and invite redemption run through the service role.
-- =============================================================================
drop policy if exists children_parent_all on public.children;
create policy children_parent_all on public.children
  for all to authenticated
  using (public.is_parent() and family_id = public.current_family_id())
  with check (public.is_parent() and family_id = public.current_family_id());

drop policy if exists children_select_self on public.children;
create policy children_select_self on public.children
  for select to authenticated
  using (id = public.my_child_id());

-- =============================================================================
-- subjects
-- =============================================================================
drop policy if exists subjects_parent_all on public.subjects;
create policy subjects_parent_all on public.subjects
  for all to authenticated
  using (public.is_parent() and child_id in (select public.my_family_child_ids()))
  with check (public.is_parent() and child_id in (select public.my_family_child_ids()));

drop policy if exists subjects_select_own on public.subjects;
create policy subjects_select_own on public.subjects
  for select to authenticated
  using (child_id = public.my_child_id());

-- =============================================================================
-- schedule_slots
-- =============================================================================
drop policy if exists schedule_slots_parent_all on public.schedule_slots;
create policy schedule_slots_parent_all on public.schedule_slots
  for all to authenticated
  using (public.is_parent() and child_id in (select public.my_family_child_ids()))
  with check (public.is_parent() and child_id in (select public.my_family_child_ids()));

drop policy if exists schedule_slots_select_own on public.schedule_slots;
create policy schedule_slots_select_own on public.schedule_slots
  for select to authenticated
  using (child_id = public.my_child_id());

-- =============================================================================
-- lessons  (the child records "what we covered" — screen C2)
-- =============================================================================
drop policy if exists lessons_parent_all on public.lessons;
create policy lessons_parent_all on public.lessons
  for all to authenticated
  using (public.is_parent() and child_id in (select public.my_family_child_ids()))
  with check (public.is_parent() and child_id in (select public.my_family_child_ids()));

drop policy if exists lessons_select_own on public.lessons;
create policy lessons_select_own on public.lessons
  for select to authenticated
  using (child_id = public.my_child_id());

drop policy if exists lessons_insert_own on public.lessons;
create policy lessons_insert_own on public.lessons
  for insert to authenticated
  with check (child_id = public.my_child_id());

drop policy if exists lessons_update_own on public.lessons;
create policy lessons_update_own on public.lessons
  for update to authenticated
  using (child_id = public.my_child_id())
  with check (child_id = public.my_child_id());

-- =============================================================================
-- topics  (scoped through subjects.child_id)
-- =============================================================================
drop policy if exists topics_parent_all on public.topics;
create policy topics_parent_all on public.topics
  for all to authenticated
  using (
    public.is_parent()
    and public.subject_child_id(subject_id) in (select public.my_family_child_ids())
  )
  with check (
    public.is_parent()
    and public.subject_child_id(subject_id) in (select public.my_family_child_ids())
  );

drop policy if exists topics_select_own on public.topics;
create policy topics_select_own on public.topics
  for select to authenticated
  using (public.subject_child_id(subject_id) = public.my_child_id());

-- =============================================================================
-- assignments
-- Row scope here; column scope in public.assignments_status_guard().
-- =============================================================================
drop policy if exists assignments_parent_all on public.assignments;
create policy assignments_parent_all on public.assignments
  for all to authenticated
  using (public.is_parent() and child_id in (select public.my_family_child_ids()))
  with check (public.is_parent() and child_id in (select public.my_family_child_ids()));

drop policy if exists assignments_select_own on public.assignments;
create policy assignments_select_own on public.assignments
  for select to authenticated
  using (child_id = public.my_child_id());

-- A child may add homework they were given, but only in the initial state.
drop policy if exists assignments_insert_own on public.assignments;
create policy assignments_insert_own on public.assignments
  for insert to authenticated
  with check (
    child_id = public.my_child_id()
    and status = 'assigned'
    and redo_count = 0
    and reviewed_by is null
    and reviewed_at is null
    and review_comment is null
  );

drop policy if exists assignments_update_own on public.assignments;
create policy assignments_update_own on public.assignments
  for update to authenticated
  using (child_id = public.my_child_id())
  with check (child_id = public.my_child_id());

-- No DELETE policy for the child.

-- =============================================================================
-- assignment_events  (append-only; written only by the SECURITY DEFINER triggers)
-- =============================================================================
drop policy if exists assignment_events_parent_select on public.assignment_events;
create policy assignment_events_parent_select on public.assignment_events
  for select to authenticated
  using (
    public.is_parent()
    and public.assignment_child_id(assignment_id) in (select public.my_family_child_ids())
  );

drop policy if exists assignment_events_child_select on public.assignment_events;
create policy assignment_events_child_select on public.assignment_events
  for select to authenticated
  using (public.assignment_child_id(assignment_id) = public.my_child_id());

-- Deliberately no INSERT/UPDATE/DELETE policies.

-- =============================================================================
-- messages
-- =============================================================================
drop policy if exists messages_parent_all on public.messages;
create policy messages_parent_all on public.messages
  for all to authenticated
  using (public.is_parent() and child_id in (select public.my_family_child_ids()))
  with check (public.is_parent() and child_id in (select public.my_family_child_ids()));

drop policy if exists messages_select_own on public.messages;
create policy messages_select_own on public.messages
  for select to authenticated
  using (child_id = public.my_child_id());

drop policy if exists messages_insert_own on public.messages;
create policy messages_insert_own on public.messages
  for insert to authenticated
  with check (child_id = public.my_child_id() and author_id = auth.uid());

drop policy if exists messages_update_author on public.messages;
create policy messages_update_author on public.messages
  for update to authenticated
  using (child_id = public.my_child_id() and author_id = auth.uid())
  with check (child_id = public.my_child_id() and author_id = auth.uid());

-- phase 2 scaffold: helper may read and post messages for children in the family
drop policy if exists messages_helper_select on public.messages;
create policy messages_helper_select on public.messages
  for select to authenticated
  using (public.is_helper() and child_id in (select public.my_family_child_ids()));

drop policy if exists messages_helper_insert on public.messages;
create policy messages_helper_insert on public.messages
  for insert to authenticated
  with check (
    public.is_helper()
    and child_id in (select public.my_family_child_ids())
    and author_id = auth.uid()
  );

-- =============================================================================
-- message_reads
-- =============================================================================
drop policy if exists message_reads_own_select on public.message_reads;
create policy message_reads_own_select on public.message_reads
  for select to authenticated
  using (user_id = auth.uid());

drop policy if exists message_reads_own_insert on public.message_reads;
create policy message_reads_own_insert on public.message_reads
  for insert to authenticated
  with check (user_id = auth.uid());

drop policy if exists message_reads_own_update on public.message_reads;
create policy message_reads_own_update on public.message_reads
  for update to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

drop policy if exists message_reads_own_delete on public.message_reads;
create policy message_reads_own_delete on public.message_reads
  for delete to authenticated
  using (user_id = auth.uid());

-- =============================================================================
-- attachments
-- =============================================================================
drop policy if exists attachments_parent_all on public.attachments;
create policy attachments_parent_all on public.attachments
  for all to authenticated
  using (public.is_parent() and child_id in (select public.my_family_child_ids()))
  with check (public.is_parent() and child_id in (select public.my_family_child_ids()));

drop policy if exists attachments_select_own on public.attachments;
create policy attachments_select_own on public.attachments
  for select to authenticated
  using (child_id = public.my_child_id());

drop policy if exists attachments_insert_own on public.attachments;
create policy attachments_insert_own on public.attachments
  for insert to authenticated
  with check (
    child_id = public.my_child_id()
    and kind in ('task_source', 'solution', 'chat')
  );

drop policy if exists attachments_update_own on public.attachments;
create policy attachments_update_own on public.attachments
  for update to authenticated
  using (child_id = public.my_child_id() and uploaded_by = auth.uid())
  with check (child_id = public.my_child_id() and uploaded_by = auth.uid());

drop policy if exists attachments_delete_own on public.attachments;
create policy attachments_delete_own on public.attachments
  for delete to authenticated
  using (child_id = public.my_child_id() and uploaded_by = auth.uid());

-- =============================================================================
-- grades  -- parent only. No child policy of any kind (SPEC section 2).
-- =============================================================================
drop policy if exists grades_parent_all on public.grades;
create policy grades_parent_all on public.grades
  for all to authenticated
  using (public.is_parent() and child_id in (select public.my_family_child_ids()))
  with check (public.is_parent() and child_id in (select public.my_family_child_ids()));

-- =============================================================================
-- topic_mastery
-- The child sees their own mastery only when the parent turned on show_own_stats.
-- =============================================================================
drop policy if exists topic_mastery_parent_all on public.topic_mastery;
create policy topic_mastery_parent_all on public.topic_mastery
  for all to authenticated
  using (public.is_parent() and child_id in (select public.my_family_child_ids()))
  with check (public.is_parent() and child_id in (select public.my_family_child_ids()));

drop policy if exists topic_mastery_select_own on public.topic_mastery;
create policy topic_mastery_select_own on public.topic_mastery
  for select to authenticated
  using (
    child_id = public.my_child_id()
    and public.child_stats_visible(child_id)
  );

-- =============================================================================
-- notifications  -- always personal
-- =============================================================================
drop policy if exists notifications_own_select on public.notifications;
create policy notifications_own_select on public.notifications
  for select to authenticated
  using (user_id = auth.uid());

drop policy if exists notifications_own_update on public.notifications;
create policy notifications_own_update on public.notifications
  for update to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

drop policy if exists notifications_own_delete on public.notifications;
create policy notifications_own_delete on public.notifications
  for delete to authenticated
  using (user_id = auth.uid());

-- No INSERT policy: notifications are produced server-side (service role).

-- ---------------------------------------------------------------------
-- 0005_storage.sql
-- ---------------------------------------------------------------------
-- =============================================================================
-- SCHOOL-HUB — 0005_storage.sql
-- Private "evidence" bucket + object policies.
-- Depends on: 0003_functions.sql
--
-- Object path convention (CLAUDE.md / SPEC section 2):
--     {child_id}/{assignment_id}/{uuid}.webp
-- Lesson-level evidence uses:
--     {child_id}/lesson/{lesson_id}/{uuid}.webp
-- In both cases the FIRST path segment is the child id, which is what the
-- policies below key on.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Bucket
-- -----------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'evidence',
  'evidence',
  false,
  10485760,  -- 10 MB hard ceiling; the client compresses to ~300 KB WebP
  array['image/webp', 'image/jpeg', 'image/png',
        'audio/webm', 'audio/mpeg', 'audio/mp4', 'audio/ogg']
)
on conflict (id) do update
  set public             = false,
      file_size_limit    = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- -----------------------------------------------------------------------------
-- Path helpers
-- -----------------------------------------------------------------------------
create or replace function public.storage_child_id(p_name text)
returns uuid
language sql
immutable
as $$
  select public.try_uuid(split_part(coalesce(p_name, ''), '/', 1));
$$;

comment on function public.storage_child_id(text) is
  'First path segment of a storage object name, as a uuid (null when it is not one).';

create or replace function public.storage_assignment_id(p_name text)
returns uuid
language sql
immutable
as $$
  select public.try_uuid(split_part(coalesce(p_name, ''), '/', 2));
$$;

revoke all on function public.storage_child_id(text) from public;
revoke all on function public.storage_assignment_id(text) from public;
grant execute on function public.storage_child_id(text) to authenticated, service_role;
grant execute on function public.storage_assignment_id(text) to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- RLS on storage.objects
-- Supabase enables it already; the guard keeps this file runnable everywhere.
-- -----------------------------------------------------------------------------
do $$
begin
  execute 'alter table storage.objects enable row level security';
exception
  when insufficient_privilege then
    raise notice 'storage.objects RLS left as-is (not the table owner) — already enabled on Supabase.';
end;
$$;

-- -----------------------------------------------------------------------------
-- Parent: anything under any child of their family
-- -----------------------------------------------------------------------------
drop policy if exists evidence_parent_all on storage.objects;
create policy evidence_parent_all on storage.objects
  for all to authenticated
  using (
    bucket_id = 'evidence'
    and public.is_parent()
    and public.storage_child_id(name) in (select public.my_family_child_ids())
  )
  with check (
    bucket_id = 'evidence'
    and public.is_parent()
    and public.storage_child_id(name) in (select public.my_family_child_ids())
  );

-- -----------------------------------------------------------------------------
-- Child: only under {their_child_id}/...
-- -----------------------------------------------------------------------------
drop policy if exists evidence_child_select on storage.objects;
create policy evidence_child_select on storage.objects
  for select to authenticated
  using (
    bucket_id = 'evidence'
    and public.storage_child_id(name) = public.my_child_id()
  );

drop policy if exists evidence_child_insert on storage.objects;
create policy evidence_child_insert on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'evidence'
    and public.storage_child_id(name) = public.my_child_id()
  );

drop policy if exists evidence_child_update on storage.objects;
create policy evidence_child_update on storage.objects
  for update to authenticated
  using (
    bucket_id = 'evidence'
    and public.storage_child_id(name) = public.my_child_id()
    and owner = auth.uid()
  )
  with check (
    bucket_id = 'evidence'
    and public.storage_child_id(name) = public.my_child_id()
  );

drop policy if exists evidence_child_delete on storage.objects;
create policy evidence_child_delete on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'evidence'
    and public.storage_child_id(name) = public.my_child_id()
    and owner = auth.uid()
  );

-- -----------------------------------------------------------------------------
-- Helper (phase 2): read-only on the family's evidence.
-- -----------------------------------------------------------------------------
drop policy if exists evidence_helper_select on storage.objects;
create policy evidence_helper_select on storage.objects
  for select to authenticated
  using (
    bucket_id = 'evidence'
    and public.is_helper()
    and public.storage_child_id(name) in (select public.my_family_child_ids())
  );

-- ---------------------------------------------------------------------
-- 0006_lesson_no_homework.sql
-- ---------------------------------------------------------------------
-- 0006_lesson_no_homework.sql
--
-- Screen C2 ("დავალება არ მოგვცეს"): the child confirms that a lesson produced no
-- homework. This has to be an explicit fact, not an inference — "no assignments yet"
-- and "no homework was given" are different states, and only the second one means the
-- child is done for that lesson.
--
-- Also adds the uniqueness that makes lesson materialisation safe: materialiseDayLessons
-- is read-then-insert, so two concurrent first loads of /kid/today could otherwise
-- create the same lesson twice.

alter table public.lessons
  add column if not exists no_homework boolean not null default false;

comment on column public.lessons.no_homework is
  'Child confirmed that this lesson produced no homework (screen C2).';

create unique index if not exists uq_lessons_child_slot_date
  on public.lessons (child_id, slot_id, date)
  where slot_id is not null;

-- ---------------------------------------------------------------------
-- 0007_privilege_hardening.sql
-- ---------------------------------------------------------------------
-- =============================================================================
-- SCHOOL-HUB — 0007_privilege_hardening.sql
-- Closes four privilege holes found in the A5 review. No schema change, so
-- `src/lib/db.types.ts` is unaffected.
-- Depends on: 0004_rls.sql, 0005_storage.sql
--
-- 1. profiles.role was self-writable  -> full parent access for any child
-- 2. messages/attachments trusted the client's child_id -> cross-sibling writes
-- 3. the child column lock on assignments covered only the review fields
-- 4. handle_new_user() read the role out of forgeable user metadata
--
-- NOTE for whoever re-runs the migrations out of order: 0004 hands
-- `authenticated` a table-wide UPDATE on every table, which would undo the
-- column grant in section 1. Run 0007 last, as its number says.
-- =============================================================================

-- =============================================================================
-- 1. profiles.role is not self-writable
--
-- `profiles_update_self` (0004) is a row policy, and a row policy cannot say
-- "every column except this one". Every parent-side RLS predicate in 0004 is
-- `public.is_parent()`, which reads `profiles.role`. A signed-in child could
-- therefore run, from the browser client the app already ships,
--
--     supabase.from('profiles').update({ role: 'parent' }).eq('id', <own id>)
--
-- and from that point `is_parent()` is true for them and
-- `current_family_id()` still resolves to their own family. That combination
-- satisfies `children_parent_all`, `grades_parent_all`, `assignments_parent_all`,
-- `messages_parent_all`, `attachments_parent_all` and `evidence_parent_all`,
-- i.e. read AND write on every sibling's homework, photos, chat and grades,
-- plus their siblings' `pin_hash` and `invite_code`, plus their own
-- `show_own_stats` / `ui_mode` / PIN lockout.
--
-- Two independent guards, because this one must not come back:
--   a) a column-level grant, so the UPDATE never reaches the policy;
--   b) a trigger, so it still fails if the grant is ever widened again.
-- Both let the service role through (auth.uid() is null there), which is how
-- `signupAction` and `redeemInviteCode` set the role in the first place.
-- =============================================================================
revoke update on public.profiles from authenticated;
grant update (display_name, avatar_url) on public.profiles to authenticated;

create or replace function public.profiles_guard_identity()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is null then
    return new;  -- service role / SQL editor / seed
  end if;

  if new.id is distinct from old.id then
    raise exception 'profiles.id cannot be changed' using errcode = '42501';
  end if;

  if new.role is distinct from old.role then
    raise exception 'profiles.role can only be changed by the service role'
      using errcode = '42501';
  end if;

  return new;
end;
$$;

comment on function public.profiles_guard_identity() is
  'BEFORE UPDATE on profiles: a signed-in user may never change their own id or role.';

drop trigger if exists trg_profiles_guard_identity on public.profiles;
create trigger trg_profiles_guard_identity
  before update on public.profiles
  for each row execute function public.profiles_guard_identity();

-- =============================================================================
-- 2. messages / attachments: child_id is derived, never accepted
--
-- The 0003 triggers only filled `child_id` when it arrived null. The RLS
-- WITH CHECK on both tables compares nothing but `child_id`, so a child could
-- post into a SIBLING's row by sending their own child_id together with the
-- sibling's assignment_id:
--
--     insert into messages (assignment_id, child_id, author_id, body)
--     values (<sibling's assignment>, <my child id>, auth.uid(), '...')
--
-- The row passes `messages_insert_own`, lands on the sibling's thread, and the
-- parent sees it on the review screen (that query filters by assignment_id, and
-- the parent policy admits any child_id in the family). Same shape for
-- attachments: a photo planted in a sibling's submission.
--
-- Deriving the value instead of validating it also makes the WITH CHECK do the
-- right thing for free — the derived child_id is the sibling's, which is not
-- `my_child_id()`, so the insert is rejected.
--
-- No app code is affected: every insert either omits child_id or already passes
-- the value read back off the owning row.
-- =============================================================================
create or replace function public.resolve_message_child_id()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_owner uuid;
begin
  v_owner := coalesce(
    (select a.child_id from public.assignments a where a.id = new.assignment_id),
    (select l.child_id from public.lessons     l where l.id = new.lesson_id)
  );

  if v_owner is null then
    raise exception 'messages.child_id could not be resolved from assignment_id/lesson_id'
      using errcode = '23502';
  end if;

  -- Authoritative: whatever the client sent is discarded.
  new.child_id := v_owner;

  -- The author is the caller. Only the service role (seed, admin scripts) may
  -- write a message on someone else's behalf.
  if auth.uid() is not null then
    new.author_id := auth.uid();
  end if;

  return new;
end;
$$;

drop trigger if exists trg_messages_resolve_child on public.messages;
create trigger trg_messages_resolve_child
  before insert on public.messages
  for each row execute function public.resolve_message_child_id();

create or replace function public.resolve_attachment_child_id()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_owner uuid;
begin
  v_owner := coalesce(
    (select a.child_id from public.assignments a where a.id = new.assignment_id),
    (select l.child_id from public.lessons     l where l.id = new.lesson_id),
    (select m.child_id from public.messages    m where m.id = new.message_id)
  );

  if v_owner is null then
    raise exception 'attachments.child_id could not be resolved from assignment_id/lesson_id/message_id'
      using errcode = '23502';
  end if;

  new.child_id := v_owner;

  if auth.uid() is not null then
    new.uploaded_by := auth.uid();
  end if;

  return new;
end;
$$;

drop trigger if exists trg_attachments_resolve_child on public.attachments;
create trigger trg_attachments_resolve_child
  before insert on public.attachments
  for each row execute function public.resolve_attachment_child_id();

-- An UPDATE must not be able to walk a row over to another child either;
-- `attachments_update_own` only re-checks child_id, not the foreign keys.
create or replace function public.attachments_guard_owner()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is null then
    return new;
  end if;

  if new.child_id      is distinct from old.child_id
     or new.assignment_id is distinct from old.assignment_id
     or new.lesson_id     is distinct from old.lesson_id
     or new.message_id    is distinct from old.message_id
     or new.storage_path  is distinct from old.storage_path then
    raise exception 'attachments ownership columns are immutable'
      using errcode = '42501';
  end if;

  return new;
end;
$$;

drop trigger if exists trg_attachments_guard_owner on public.attachments;
create trigger trg_attachments_guard_owner
  before update on public.attachments
  for each row execute function public.attachments_guard_owner();

-- =============================================================================
-- 3. assignments: the child column lock now matches SPEC section 2
--
-- SPEC: a child "changes only: the move to submitted, self_rating,
-- difficulty_note, minutes_spent, their own files". `assignments_update_own`
-- grants a row-wide UPDATE and 0003's trigger only locked review_comment,
-- reviewed_by, reviewed_at and redo_count — so a child could rewrite the title,
-- the source reference and the due date of homework their parent set, after the
-- fact and without an audit entry ("Maths p.45 ex.3" quietly becomes "ex.1",
-- Friday's deadline becomes next Wednesday).
--
-- This replaces the 0003 function wholesale; everything else in it is
-- unchanged, including the audit-comment logic.
-- =============================================================================
create or replace function public.assignments_status_guard()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid           uuid    := auth.uid();
  v_service       boolean := (auth.uid() is null);
  v_child_profile uuid;
  v_is_child      boolean;
  v_can_review    boolean;
  v_transition    text;
  v_comment       text;
begin
  select c.profile_id into v_child_profile
    from public.children c
   where c.id = new.child_id;

  v_is_child   := (v_uid is not null and v_uid is not distinct from v_child_profile);
  v_can_review := (not v_service) and public.can_review(new.child_id);

  -- ---------------------------------------------------------------- ownership
  if new.child_id is distinct from old.child_id and not v_service then
    raise exception 'assignments.child_id cannot be changed'
      using errcode = '42501';
  end if;

  -- ------------------------------------------------------- child column lock
  if v_is_child and not v_can_review then
    -- reviewer-owned columns
    if new.review_comment is distinct from old.review_comment then
      raise exception 'A child may not change review_comment' using errcode = '42501';
    end if;
    if new.reviewed_by is distinct from old.reviewed_by then
      raise exception 'A child may not change reviewed_by' using errcode = '42501';
    end if;
    if new.reviewed_at is distinct from old.reviewed_at then
      raise exception 'A child may not change reviewed_at' using errcode = '42501';
    end if;
    if new.redo_count is distinct from old.redo_count then
      raise exception 'A child may not change redo_count' using errcode = '42501';
    end if;

    -- the assignment as the parent set it. `submitted_at` is checked before the
    -- transition block below stamps it, so handing work in is still allowed.
    if new.title is distinct from old.title
       or new.description is distinct from old.description
       or new.source_ref  is distinct from old.source_ref
       or new.due_date    is distinct from old.due_date
       or new.due_time    is distinct from old.due_time
       or new.subject_id  is distinct from old.subject_id
       or new.topic_id    is distinct from old.topic_id
       or new.lesson_id   is distinct from old.lesson_id
       or new.priority    is distinct from old.priority
       or new.ai_check    is distinct from old.ai_check
       or new.created_by  is distinct from old.created_by
       or new.created_at  is distinct from old.created_at
       or new.submitted_at is distinct from old.submitted_at then
      raise exception 'A child may only change status, self_rating, difficulty_note and minutes_spent'
        using errcode = '42501';
    end if;
  end if;

  -- -------------------------------------------------------------- transition
  if new.status is not distinct from old.status then
    return new;
  end if;

  v_transition := old.status || '->' || new.status;

  if v_transition not in (
       'assigned->in_progress',
       'assigned->submitted',
       'in_progress->submitted',
       'submitted->approved',
       'submitted->redo',
       'redo->in_progress',
       'approved->redo',
       'approved->in_progress'
     ) then
    raise exception 'Illegal assignment status transition: % -> %', old.status, new.status
      using errcode = '23514';
  end if;

  -- corrections out of an already approved assignment are reviewer-only
  if old.status = 'approved' and not (v_can_review or v_service) then
    raise exception 'Only a parent (or a helper with review rights) may reopen an approved assignment'
      using errcode = '42501';
  end if;

  -- approve / return for redo are reviewer-only
  if new.status in ('approved', 'redo') then
    if not (v_can_review or v_service) then
      raise exception 'Only a parent (or a helper with review rights) may set status to %', new.status
        using errcode = '42501';
    end if;
    new.reviewed_at := now();
    new.reviewed_by := v_uid;
  end if;

  if new.status = 'submitted' then
    new.submitted_at := now();
  end if;

  if old.status = 'redo' and new.status = 'in_progress' then
    new.redo_count := coalesce(old.redo_count, 0) + 1;
  end if;

  -- ------------------------------------------------------------------ audit
  -- On a review decision always record the comment that was in force, even when it
  -- repeats the previous one. Returning the same work twice with the same wording is
  -- exactly the case the audit trail exists to show; de-duplicating it would hide
  -- the second rejection.
  v_comment := case
                 when new.status in ('approved', 'redo')
                   then new.review_comment
                 when new.review_comment is distinct from old.review_comment
                   then new.review_comment
                 else null
               end;

  insert into public.assignment_events
    (assignment_id, actor_id, from_status, to_status, comment)
  values
    (new.id, v_uid, old.status, new.status, v_comment);

  return new;
end;
$$;

drop trigger if exists trg_assignments_status_guard on public.assignments;
create trigger trg_assignments_status_guard
  before update on public.assignments
  for each row execute function public.assignments_status_guard();

-- =============================================================================
-- 4. handle_new_user(): the role comes from app metadata, not user metadata
--
-- `raw_user_meta_data` is whatever the caller put in `signUp({ options: { data } })`,
-- so it is attacker-controlled. `raw_app_meta_data` can only be written with the
-- service role, which is exactly where the child provisioning in
-- `src/lib/auth/child.ts` sets `{ role: 'child' }`. Without this, a freshly
-- provisioned child briefly holds `profiles.role = 'parent'` — the window
-- between `admin.auth.admin.createUser()` and the profile upsert that follows it.
-- =============================================================================
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_role text;
begin
  v_role := coalesce(
    new.raw_app_meta_data  ->> 'role',
    new.raw_user_meta_data ->> 'role',
    'parent'
  );
  if v_role not in ('parent', 'child', 'helper') then
    v_role := 'parent';
  end if;

  insert into public.profiles (id, role, display_name, avatar_url)
  values (
    new.id,
    v_role,
    coalesce(
      nullif(btrim(new.raw_user_meta_data ->> 'display_name'), ''),
      nullif(split_part(coalesce(new.email, ''), '@', 1), ''),
      'user'
    ),
    new.raw_user_meta_data ->> 'avatar_url'
  )
  on conflict (id) do nothing;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- The new functions are left with the default privileges, exactly like
-- the trigger functions in 0003: a trigger function cannot be called usefully
-- by hand (NEW/OLD are unbound, so it raises immediately), and PostgreSQL only
-- checks EXECUTE when the trigger is created, not when it fires.

-- ---------------------------------------------------------------------
-- 0008_sibling_identity_scope.sql
-- ---------------------------------------------------------------------
-- =============================================================================
-- SCHOOL-HUB — 0008_sibling_identity_scope.sql
-- Closes the last two rows a child could read that belong to a sibling.
-- Depends on: 0004_rls.sql (and must run after it, like 0007)
--
-- Found by supabase/test/rls.test.mjs, which walks EVERY public table as child
-- A and asks for child B's rows. Fourteen of the sixteen tables returned zero.
-- Two did not:
--
--   profiles        `profiles_select_self_or_family` (0004) admits
--                   `id in (select public.my_family_user_ids())`, and
--                   `my_family_user_ids()` deliberately includes every child of
--                   the family. So child A could read child B's profile row:
--                   auth user id, role, display_name, avatar_url.
--
--   family_members  `family_members_select` (0004) admits
--                   `family_id = public.current_family_id()`, i.e. the whole
--                   membership table of the family, including the sibling's
--                   row: their auth user id, role and permissions jsonb.
--
-- Severity: low but not zero. No policy anywhere keys on a client-supplied
-- user id -- every child-side predicate goes through `public.my_child_id()`,
-- which is derived from `auth.uid()` -- so knowing the sibling's uuid does not
-- by itself unlock anything. What it does do is contradict the SPEC, which
-- says in section 1 that a child "technically cannot see a sibling's data",
-- and it hands an attacker the identifiers to aim at if any future policy is
-- ever written against a supplied id instead of auth.uid(). A nine-year-old
-- being able to enumerate their sibling's account is also simply not what the
-- parent was promised.
--
-- Not fixed by narrowing `my_family_user_ids()`: that helper is also what makes
-- a PARENT able to see the whole family, which is correct. The scope belongs in
-- the policy, conditioned on who is asking.
--
-- What a child still sees, because the UI needs it: their own profile row, and
-- the profile + membership rows of the adults in the family (the parent's
-- display_name renders as the author on every chat message and every
-- assignment_events actor -- see src/features/messages/queries.ts and
-- src/features/assignments/queries.ts, both of which select display_name by
-- author/actor id).
--
-- Written as a new migration rather than an edit to 0004 for the same reason
-- 0007 was: 0004 states the baseline model and these files are the record of
-- what the security review found. Applying 0001..0008 in order is the only
-- supported path either way.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Profile ids of the OTHER children in the caller's family.
-- Empty for a parent or helper (my_child_id() is null for them, so the guard in
-- each policy below switches this check off entirely rather than relying on
-- this function returning nothing).
-- -----------------------------------------------------------------------------
create or replace function public.sibling_profile_ids()
returns setof uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select c.profile_id
    from public.children c
   where c.family_id = public.current_family_id()
     and c.profile_id is not null
     and c.id is distinct from public.my_child_id();
$$;

comment on function public.sibling_profile_ids() is
  'Auth user ids of the other children in the caller''s family. Meaningful only when the caller is a child.';

revoke all on function public.sibling_profile_ids() from public;
grant execute on function public.sibling_profile_ids() to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- profiles: self, plus the family -- minus siblings when the caller is a child.
-- -----------------------------------------------------------------------------
drop policy if exists profiles_select_self_or_family on public.profiles;
create policy profiles_select_self_or_family on public.profiles
  for select to authenticated
  using (
    id = auth.uid()
    or (
      id in (select public.my_family_user_ids())
      and (
        not public.is_child()
        or id not in (select public.sibling_profile_ids())
      )
    )
  );

-- -----------------------------------------------------------------------------
-- family_members: own row, plus the family -- minus siblings for a child.
-- -----------------------------------------------------------------------------
drop policy if exists family_members_select on public.family_members;
create policy family_members_select on public.family_members
  for select to authenticated
  using (
    user_id = auth.uid()
    or (
      family_id = public.current_family_id()
      and (
        not public.is_child()
        or user_id not in (select public.sibling_profile_ids())
      )
    )
  );

-- ---------------------------------------------------------------------
-- 0009_realtime_notifications.sql
-- ---------------------------------------------------------------------
-- =============================================================================
-- SCHOOL-HUB — 0009_realtime_notifications.sql
-- Phase 2, communication layer: live chat + in-app notifications.
-- Depends on: 0004_rls.sql (policies), 0007/0008 (hardening). No schema change
-- to any table, so `src/lib/db.types.ts` is unaffected and is NOT regenerated.
--
-- Three things live in here and nothing else:
--
--   1. Realtime  — `messages` and `notifications` join the `supabase_realtime`
--                  publication, with their replica identity pinned and argued
--                  for (section 1).
--   2. Delivery  — `public.enqueue_notification()`, the ONLY writer of
--                  `public.notifications`. SECURITY DEFINER, because 0004
--                  deliberately gives that table no INSERT policy: a browser
--                  must never be able to fabricate a notification for itself
--                  or for anybody else (section 2).
--   3. Triggers  — submit / approve / redo / message-posted (section 3).
--
-- Design rule that runs through all of it: a notification row must be
-- renderable on its own. The bell reads `notifications` and nothing else, so
-- every string it shows (child name, subject name, assignment title, author
-- name, preview) is denormalised into `payload` at write time. That trades a
-- little staleness — renaming a subject does not rewrite old notifications —
-- for a list that costs exactly one query no matter how many rows it holds.
-- =============================================================================


-- =============================================================================
-- 1. Realtime publication membership
--
-- Supabase Realtime tails logical replication of the `supabase_realtime`
-- publication and re-broadcasts each change to subscribed clients, running the
-- table's RLS SELECT policies against the changed record as the subscribing
-- user. Being in the publication is therefore NOT a grant: it decides what
-- Realtime can see, while RLS still decides who receives it.
--
-- Replica identity: DEFAULT (primary key) on both tables, deliberately, not
-- FULL.
--   * INSERT — which is all the UI consumes — always carries the complete new
--     tuple regardless of replica identity, and Realtime checks RLS against
--     that tuple. So FULL buys nothing for the case we actually use.
--   * UPDATE/DELETE with FULL would put the entire PREVIOUS row into the WAL
--     record. Realtime applies RLS to the new record; the old record is not
--     filtered the same way. With FULL, deleting a message would broadcast its
--     body to every subscriber of the table. With DEFAULT the old record is a
--     bare primary key, so the worst case is a leaked uuid.
--   * Neither table is ever UPDATEd in a way the UI needs the old values for
--     (messages.edited_at, notifications.read_at), so DEFAULT costs us nothing.
-- The client subscribes to INSERT only for messages and to INSERT/UPDATE for
-- notifications; see src/lib/realtime/.
-- =============================================================================
do $$
declare
  v_all_tables boolean;
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    -- A real Supabase project already has this publication; a bare Postgres
    -- (the test harness in supabase/test/) does not.
    execute 'create publication supabase_realtime';
  end if;

  select p.puballtables into v_all_tables
    from pg_publication p
   where p.pubname = 'supabase_realtime';

  -- `for all tables` publications cannot take an explicit table list.
  if coalesce(v_all_tables, false) then
    raise notice 'supabase_realtime is FOR ALL TABLES; messages and notifications are already published';
  else
    if not exists (
      select 1 from pg_publication_tables
       where pubname = 'supabase_realtime'
         and schemaname = 'public'
         and tablename = 'messages'
    ) then
      execute 'alter publication supabase_realtime add table public.messages';
    end if;

    if not exists (
      select 1 from pg_publication_tables
       where pubname = 'supabase_realtime'
         and schemaname = 'public'
         and tablename = 'notifications'
    ) then
      execute 'alter publication supabase_realtime add table public.notifications';
    end if;
  end if;
end;
$$;

-- Stated explicitly even though DEFAULT is the server default: this is the
-- security decision above, written down where it is enforced.
alter table public.messages      replica identity default;
alter table public.notifications replica identity default;

-- `message_reads` is NOT published. Read receipts are per-viewer bookkeeping;
-- broadcasting them would tell one side exactly when the other opened the
-- thread, which nothing in the SPEC asks for.


-- =============================================================================
-- 2. Notification delivery
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 2a. No client may INSERT, and no client may rewrite a delivered notification.
--
-- 0004 gives `notifications` SELECT/UPDATE/DELETE policies for the owner and no
-- INSERT policy, so RLS already rejects a client INSERT. Revoking the grant as
-- well makes it a privilege failure BEFORE the policy is consulted — two
-- independent guards, in the style of 0007.
-- -----------------------------------------------------------------------------
revoke insert on public.notifications from authenticated;
revoke insert on public.notifications from anon;

-- The owner keeps UPDATE, but only over `read_at`. Without this a user could
-- take a real notification and rewrite its `type` and `payload` — self-inflicted
-- only, since RLS still confines them to their own rows, but a notification is
-- an audit-ish artefact and "the row you were sent is the row you see" is worth
-- one trigger. Service context (auth.uid() is null) is left alone so migrations
-- and admin scripts are not blocked, exactly as 0003/0007 do.
--
-- `enqueue_notification()` collapses a burst by UPDATEing an existing row, and
-- it runs inside the caller's transaction, so auth.uid() is still the end user
-- there — SECURITY DEFINER changes the executing role, not the JWT GUC. It
-- therefore raises a transaction-local flag around its own write, which this
-- guard honours. PostgREST gives a client no way to run `set_config`, and even
-- if it could the only thing it would unlock is rewriting the payload of a
-- notification addressed to itself.
create or replace function public.notifications_owner_update_guard()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is null
     or coalesce(current_setting('schoolhub.notification_writer', true), '') = 'on'
  then
    return new;
  end if;

  if new.user_id is distinct from old.user_id then
    raise exception 'notifications.user_id cannot be changed' using errcode = '42501';
  end if;
  if new.type is distinct from old.type then
    raise exception 'notifications.type cannot be changed' using errcode = '42501';
  end if;
  if new.payload is distinct from old.payload then
    raise exception 'notifications.payload cannot be changed' using errcode = '42501';
  end if;
  if new.created_at is distinct from old.created_at then
    raise exception 'notifications.created_at cannot be changed' using errcode = '42501';
  end if;

  return new;
end;
$$;

drop trigger if exists trg_notifications_owner_update_guard on public.notifications;
create trigger trg_notifications_owner_update_guard
  before update on public.notifications
  for each row execute function public.notifications_owner_update_guard();

-- -----------------------------------------------------------------------------
-- 2b. enqueue_notification — the single writer.
--
-- Collapsing: a burst of messages in one thread must not become a column of
-- identical rows in the bell. If the recipient already has an UNREAD row of the
-- same type about the same assignment, created inside `p_collapse_window`, that
-- row is updated instead: payload refreshed to the newest event, `count`
-- accumulated, `created_at` moved to now() so the thread surfaces at the top of
-- a created_at-desc list.
--
-- The window slides on purpose. A drip of one message every few minutes that
-- the user never opens is still ONE unread conversation, and should stay one
-- row saying "4 new messages". As soon as the row is read, the next event
-- starts a fresh one — that is what `read_at is null` buys.
--
-- Returns the id of the row written or updated, or null when there was nobody
-- to notify.
-- -----------------------------------------------------------------------------
create or replace function public.enqueue_notification(
  p_user_id         uuid,
  p_type            text,
  p_payload         jsonb,
  p_collapse_window interval default interval '10 minutes'
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_existing uuid;
  v_payload  jsonb := coalesce(p_payload, '{}'::jsonb);
begin
  if p_user_id is null or p_type is null then
    return null;
  end if;

  -- Only deliver to a real profile. A child who has not redeemed their invite
  -- code has no profile_id, and the FK would raise.
  if not exists (select 1 from public.profiles p where p.id = p_user_id) then
    return null;
  end if;

  if not (v_payload ? 'count') then
    v_payload := v_payload || jsonb_build_object('count', 1);
  end if;

  select n.id
    into v_existing
    from public.notifications n
   where n.user_id = p_user_id
     and n.type = p_type
     and n.read_at is null
     and n.created_at > now() - p_collapse_window
     -- `is not distinct from` so two notifications that are both about no
     -- assignment collapse together as well.
     and (n.payload ->> 'assignment_id') is not distinct from (v_payload ->> 'assignment_id')
   order by n.created_at desc
   limit 1
   for update;

  if v_existing is not null then
    -- Transaction-local; see notifications_owner_update_guard() above.
    perform set_config('schoolhub.notification_writer', 'on', true);
    update public.notifications
       set payload = v_payload || jsonb_build_object(
             'count',
             coalesce(nullif(payload ->> 'count', '')::int, 1)
             + coalesce(nullif(v_payload ->> 'count', '')::int, 1)
           ),
           created_at = now()
     where id = v_existing;
    perform set_config('schoolhub.notification_writer', 'off', true);
    return v_existing;
  end if;

  insert into public.notifications (user_id, type, payload)
  values (p_user_id, p_type, v_payload)
  returning id into v_existing;

  return v_existing;
end;
$$;

comment on function public.enqueue_notification(uuid, text, jsonb, interval) is
  'Sole writer of public.notifications. SECURITY DEFINER; never granted to a client role.';

-- Not callable over PostgREST by anyone. The triggers below reach it because
-- they are themselves SECURITY DEFINER and owned by the same role.
revoke all on function public.enqueue_notification(uuid, text, jsonb, interval) from public;
revoke all on function public.enqueue_notification(uuid, text, jsonb, interval) from anon;
revoke all on function public.enqueue_notification(uuid, text, jsonb, interval) from authenticated;

-- -----------------------------------------------------------------------------
-- 2c. Who are "the parents" of a family?
-- The family owner plus every family_members row with role = 'parent'.
-- Helpers are deliberately excluded: the helper role is defined in 0010 and
-- notifying it is that migration's call to make, not this one's.
-- -----------------------------------------------------------------------------
create or replace function public.family_parent_ids(p_family_id uuid)
returns setof uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select f.owner_id
    from public.families f
   where f.id = p_family_id
     and f.owner_id is not null
  union
  select fm.user_id
    from public.family_members fm
   where fm.family_id = p_family_id
     and fm.role = 'parent';
$$;

comment on function public.family_parent_ids(uuid) is
  'Auth user ids of the adults who own/parent this family. Used by the notification triggers.';

revoke all on function public.family_parent_ids(uuid) from public;
grant execute on function public.family_parent_ids(uuid) to service_role;


-- =============================================================================
-- 3. Triggers
--
-- Notification types, and who gets them:
--
--   assignment_submitted   child submitted        -> every parent in the family
--   assignment_approved    parent set 'approved'  -> that child
--   assignment_redo        parent set 'redo'      -> that child
--   message_posted         message written        -> the OTHER side of the
--                                                    thread (child -> parents,
--                                                    adult -> child)
--
-- Nobody is ever notified about their own action: every recipient is compared
-- against auth.uid() first. In service context (auth.uid() is null — seeds,
-- migrations, admin scripts) there is no actor to exclude, so everyone on the
-- receiving side is notified; that is what makes supabase/seed.sql produce a
-- realistic bell without a second seed section.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 3a. Status changes.
-- AFTER UPDATE, so it observes the row the BEFORE trigger in 0003
-- (assignments_status_guard) has already validated and stamped.
-- -----------------------------------------------------------------------------
create or replace function public.notify_assignment_status()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor      uuid := auth.uid();
  v_child_name text;
  v_family_id  uuid;
  v_child_user uuid;
  v_subject    text;
  v_payload    jsonb;
  v_recipient  uuid;
begin
  if new.status is not distinct from old.status then
    return null;
  end if;

  if new.status not in ('submitted', 'approved', 'redo') then
    return null;
  end if;

  select c.name, c.family_id, c.profile_id
    into v_child_name, v_family_id, v_child_user
    from public.children c
   where c.id = new.child_id;

  if v_family_id is null then
    return null;
  end if;

  select s.name into v_subject
    from public.subjects s
   where s.id = new.subject_id;

  if new.status = 'submitted' then
    v_payload := jsonb_build_object(
      'v',            1,
      'audience',     'parent',
      'count',        1,
      'assignment_id', new.id,
      'child_id',     new.child_id,
      'child_name',   v_child_name,
      'subject_name', v_subject,
      'title',        left(new.title, 120)
    );

    for v_recipient in
      select u from public.family_parent_ids(v_family_id) as u
    loop
      if v_recipient is distinct from v_actor then
        perform public.enqueue_notification(v_recipient, 'assignment_submitted', v_payload);
      end if;
    end loop;

    return null;
  end if;

  -- approved | redo -> the child whose work it is
  if v_child_user is null or v_child_user is not distinct from v_actor then
    return null;
  end if;

  v_payload := jsonb_build_object(
    'v',            1,
    'audience',     'child',
    'count',        1,
    'assignment_id', new.id,
    'child_id',     new.child_id,
    'child_name',   v_child_name,
    'subject_name', v_subject,
    'title',        left(new.title, 120),
    'preview',      nullif(left(coalesce(new.review_comment, ''), 120), '')
  );

  perform public.enqueue_notification(
    v_child_user,
    case when new.status = 'approved' then 'assignment_approved' else 'assignment_redo' end,
    v_payload
  );

  return null;
end;
$$;

drop trigger if exists trg_assignments_notify_status on public.assignments;
create trigger trg_assignments_notify_status
  after update on public.assignments
  for each row execute function public.notify_assignment_status();

-- -----------------------------------------------------------------------------
-- 3b. Messages.
--
-- "The other side" is literal: a thread has a child side and an adult side.
-- The child's message goes to the parents; an adult's message goes to the
-- child. A second parent is NOT notified when the first parent writes — they
-- can read the thread whenever they like, and a reply between adults is not
-- news for the other adult. Revisit if a family ever complains.
--
-- Lesson-scoped messages (assignment_id null) are skipped: there is no screen
-- for them yet, so a notification would link nowhere.
-- -----------------------------------------------------------------------------
create or replace function public.notify_message_posted()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor      uuid := coalesce(new.author_id, auth.uid());
  v_child_name text;
  v_family_id  uuid;
  v_child_user uuid;
  v_title      text;
  v_subject    text;
  v_actor_name text;
  v_payload    jsonb;
  v_recipient  uuid;
  v_from_child boolean;
begin
  if new.assignment_id is null then
    return null;
  end if;

  select c.name, c.family_id, c.profile_id
    into v_child_name, v_family_id, v_child_user
    from public.children c
   where c.id = new.child_id;

  if v_family_id is null then
    return null;
  end if;

  select a.title, s.name
    into v_title, v_subject
    from public.assignments a
    left join public.subjects s on s.id = a.subject_id
   where a.id = new.assignment_id;

  if v_actor is not null then
    select p.display_name into v_actor_name
      from public.profiles p
     where p.id = v_actor;
  end if;
  -- A child's display_name is their auth-user name; children.name is what the
  -- family actually calls them and what every other screen shows.
  if v_actor is not null and v_actor is not distinct from v_child_user then
    v_actor_name := coalesce(v_child_name, v_actor_name);
  end if;

  v_payload := jsonb_build_object(
    'v',            1,
    'count',        1,
    'assignment_id', new.assignment_id,
    'child_id',     new.child_id,
    'child_name',   v_child_name,
    'subject_name', v_subject,
    'title',        left(coalesce(v_title, ''), 120),
    'actor_name',   v_actor_name,
    'preview',      nullif(left(coalesce(new.body, ''), 120), '')
  );

  v_from_child := (v_actor is not null and v_actor is not distinct from v_child_user);

  if v_from_child then
    -- child -> every parent
    for v_recipient in
      select u from public.family_parent_ids(v_family_id) as u
    loop
      if v_recipient is distinct from v_actor then
        perform public.enqueue_notification(
          v_recipient,
          'message_posted',
          v_payload || jsonb_build_object('audience', 'parent')
        );
      end if;
    end loop;
    return null;
  end if;

  -- adult (or service context) -> the child
  if v_child_user is null or v_child_user is not distinct from v_actor then
    return null;
  end if;

  perform public.enqueue_notification(
    v_child_user,
    'message_posted',
    v_payload || jsonb_build_object('audience', 'child')
  );

  return null;
end;
$$;

drop trigger if exists trg_messages_notify on public.messages;
create trigger trg_messages_notify
  after insert on public.messages
  for each row execute function public.notify_message_posted();


-- =============================================================================
-- 4. Index supporting the collapse lookup and the bell's own query.
-- The partial index from 0002 is (user_id, created_at desc) where read_at is
-- null, which the collapse lookup already uses; this one covers the bell's
-- "newest 20 of mine, read or not".
-- =============================================================================
create index if not exists idx_notifications_user_created
  on public.notifications (user_id, created_at desc);

-- ---------------------------------------------------------------------
-- 0010_helper_role.sql
-- ---------------------------------------------------------------------
-- =============================================================================
-- SCHOOL-HUB — 0010_helper_role.sql
-- The helper role, completed. Depends on: 0004_rls.sql, 0005_storage.sql,
-- 0007_privilege_hardening.sql, 0008_sibling_identity_scope.sql.
--
-- A helper is an adult the parent trusts with ONE child's homework: a
-- grandparent, a tutor, a second parent who does not run the family. SPEC
-- section 1 promises "the parent sends an email invitation, picks which child
-- and with what right (view / view + comment)". 0004 only scaffolded that: it
-- gave `is_helper()` a family-wide SELECT on messages and 0005 gave the same
-- role a family-wide SELECT on every evidence object. Family-wide is exactly
-- what a helper must not have, and neither scaffold said anything about the
-- other fifteen tables.
--
-- What this migration settles.
--
--   scope     Per child, from an EXPLICIT list in `family_members.permissions`.
--             0003's `can_review()` treated an absent list as "every child in
--             the family" — a fail-OPEN default in the one place that decides
--             who may mark a child's homework done. Here the list is required:
--             no array, no access, for viewing and for reviewing alike.
--
--   rights    view      — always, for the listed children only
--             comment   — optional, `permissions.can_comment`
--             review    — optional, `permissions.can_review`, OFF by default
--
--   never     children (the row itself, so never `invite_code`, `pin_hash`,
--             `pin_attempts`, `pin_locked_until`, `ui_mode`, `show_own_stats`),
--             grades, topic_mastery, families, other family_members rows,
--             any INSERT/UPDATE/DELETE on subjects, topics, schedule_slots,
--             lessons, assignments-except-a-review-decision, attachments, or
--             any write at all to storage.
--
--   revoke    `permissions.revoked_at` on the membership row. Every function
--             below treats a stamped row as if it were not there, so access
--             stops on the next statement. The row itself stays, and so do the
--             helper's messages and their author's name — removing someone
--             must not delete their words or turn them into "unknown".
--
-- `permissions` jsonb for a helper membership:
--
--     {
--       "children":   ["<child uuid>", ...],   -- required, explicit, non-empty
--       "can_comment": true | false,
--       "can_review":  true | false,           -- default false
--       "revoked_at":  "<timestamptz>"         -- absent while active
--     }
--
-- Nothing here touches the child-side or parent-side policies, so the 0007 and
-- 0008 guarantees are unchanged; sections 2 and 9 re-state why a helper cannot
-- be used as a lever against either.
-- =============================================================================

-- =============================================================================
-- 1. Scope functions
--
-- All SECURITY DEFINER + STABLE, like every helper in 0003: a policy on table X
-- must be able to look into family_members without tripping its own RLS.
-- All of them are keyed on auth.uid() alone — none takes a caller-supplied user
-- id, so none can be pointed at somebody else.
-- =============================================================================

-- Truthiness of a permissions flag, spelled the same way everywhere.
create or replace function public.jsonb_flag(p_permissions jsonb, p_flag text)
returns boolean
language sql
immutable
as $$
  select lower(coalesce(p_permissions ->> p_flag, 'false'))
         in ('true', 't', '1', 'yes');
$$;

comment on function public.jsonb_flag(jsonb, text) is
  'Reads a boolean-ish flag out of a permissions jsonb. Absent or unparseable => false.';

-- The children a helper is assigned to, as real rows.
--
-- The join back to `children` is deliberate: an id left behind in the jsonb
-- after the child was deleted, or moved to another family, resolves to nothing.
-- The list is the parent's statement of intent; the join is what makes it true.
create or replace function public.helper_child_ids()
returns setof uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select distinct c.id
    from public.family_members fm
    cross join lateral jsonb_array_elements_text(
      case
        when jsonb_typeof(fm.permissions -> 'children') = 'array'
          then fm.permissions -> 'children'
        else '[]'::jsonb
      end
    ) as listed(child_id)
    join public.children c
      on c.id = public.try_uuid(listed.child_id)
     and c.family_id = fm.family_id
   where fm.user_id = auth.uid()
     and fm.role = 'helper'
     and fm.permissions ->> 'revoked_at' is null;
$$;

comment on function public.helper_child_ids() is
  'Children the calling helper is assigned to. Empty for anyone else, and empty once the membership is revoked.';

-- One predicate for "the caller is an active helper for this child".
-- `is_helper()` (profiles.role) AND the membership row must agree; an account
-- that is a parent somewhere else does not get helper powers here by holding a
-- helper membership, and vice versa.
create or replace function public.helper_sees_child(p_child_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select public.is_helper()
     and p_child_id is not null
     and p_child_id in (select public.helper_child_ids());
$$;

comment on function public.helper_sees_child(uuid) is
  'True when the caller is an active helper assigned to this child. The single read predicate for every helper policy.';

create or replace function public.helper_can_comment(p_child_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select public.is_helper()
     and exists (
       select 1
         from public.family_members fm
         join public.children c
           on c.family_id = fm.family_id
          and c.id = p_child_id
        where fm.user_id = auth.uid()
          and fm.role = 'helper'
          and fm.permissions ->> 'revoked_at' is null
          and public.jsonb_flag(fm.permissions, 'can_comment')
          and jsonb_typeof(fm.permissions -> 'children') = 'array'
          and (fm.permissions -> 'children') ? (p_child_id::text)
     );
$$;

comment on function public.helper_can_comment(uuid) is
  'True when the caller is an active helper allowed to post messages for this child.';

-- -----------------------------------------------------------------------------
-- can_review(), fail-closed.
--
-- Three changes to the 0003 version, parent behaviour untouched:
--   a) the "no children array means every child" fallback is gone. An explicit
--      array containing this child is now required.
--   b) a revoked membership grants nothing.
--   c) the helper branch additionally requires profiles.role = 'helper', so
--      "who is a helper" has exactly one answer across the whole schema.
-- -----------------------------------------------------------------------------
create or replace function public.can_review(p_child_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
      from public.children c
      join public.families f on f.id = c.family_id
     where c.id = p_child_id
       and f.owner_id = auth.uid()
  )
  or exists (
    select 1
      from public.children c
      join public.family_members fm on fm.family_id = c.family_id
     where c.id = p_child_id
       and fm.user_id = auth.uid()
       and fm.role = 'parent'
  )
  or (
    public.is_helper()
    and exists (
      select 1
        from public.children c
        join public.family_members fm on fm.family_id = c.family_id
       where c.id = p_child_id
         and fm.user_id = auth.uid()
         and fm.role = 'helper'
         and fm.permissions ->> 'revoked_at' is null
         and public.jsonb_flag(fm.permissions, 'can_review')
         and jsonb_typeof(fm.permissions -> 'children') = 'array'
         and (fm.permissions -> 'children') ? (p_child_id::text)
    )
  );
$$;

comment on function public.can_review(uuid) is
  'True when the caller may approve/return this child''s work: the family owner, a parent member, or an active helper explicitly granted can_review for this child.';

do $$
declare
  fn text;
  fns text[] := array[
    'public.jsonb_flag(jsonb, text)',
    'public.helper_child_ids()',
    'public.helper_sees_child(uuid)',
    'public.helper_can_comment(uuid)',
    'public.can_review(uuid)'
  ];
begin
  foreach fn in array fns loop
    execute format('revoke all on function %s from public', fn);
    execute format('grant execute on function %s to authenticated, service_role', fn);
  end loop;
end;
$$;

-- =============================================================================
-- 2. children: a helper reads a VIEW, never the table
--
-- A helper needs a name, a colour and an avatar to render "Nika's homework".
-- The same row also carries `invite_code` — which redeems into the child's own
-- account — and `pin_hash`, `pin_attempts`, `pin_locked_until`, `ui_mode` and
-- `show_own_stats`. RLS is row-level: a SELECT policy on `children` hands over
-- whole rows, and a column-level GRANT cannot help because parent and helper
-- are both the single Postgres role `authenticated`.
--
-- So the helper gets no policy on `public.children` at all, and a view that
-- does not mention the sensitive columns anywhere. Deliberately NOT
-- `security_invoker`: the view runs as its owner, which is the only way it can
-- read a table the caller has no policy on. Its own WHERE clause is the whole
-- access rule, and `helper_child_ids()` is empty for everyone who is not an
-- active helper, so a parent or a child selecting from this view gets nothing.
-- =============================================================================
drop view if exists public.helper_children;
create view public.helper_children
with (security_barrier = true) as
  select
    c.id,
    c.family_id,
    c.name,
    c.grade,
    c.school,
    c.birth_date,
    c.avatar_url,
    c.color,
    c.is_active
  from public.children c
  where c.id in (select public.helper_child_ids());

comment on view public.helper_children is
  'The children the calling helper is assigned to, without invite_code, pin_hash, pin_attempts, pin_locked_until, ui_mode or show_own_stats. Empty for every other caller.';

revoke all on public.helper_children from public;
revoke all on public.helper_children from anon;
grant select on public.helper_children to authenticated, service_role;

-- =============================================================================
-- 3. helper_invitations
--
-- An adult with their own email and password, so not the child flow: no PIN,
-- no 6-character code typed on a phone. A row here is a pending offer; on
-- acceptance it becomes a `family_members` row and the invitation is stamped.
--
-- The token is stored as issued rather than hashed, for the same reason
-- `children.invite_code` is: sending email is out of scope, so the parent has
-- to be able to re-open the page and copy the link again. It is 160+ bits of
-- CSPRNG output, single-use, expiring, and readable only by the family owner
-- (the redemption path itself runs as service_role, never as `authenticated`).
-- Once real email exists, hash it and show it once.
-- =============================================================================
create table if not exists public.helper_invitations (
  id           uuid        primary key default gen_random_uuid(),
  family_id    uuid        not null references public.families (id) on delete cascade,
  email        text        not null check (length(btrim(email)) between 3 and 320),
  token        text        not null unique
                           check (length(token) between 16 and 64),
  -- cardinality(), not array_length(): array_length('{}', 1) is NULL and a
  -- CHECK that evaluates to NULL passes, so an invitation granting nothing
  -- would slip through. No default either — naming a child is the whole point.
  child_ids    uuid[]      not null
                           check (cardinality(child_ids) between 1 and 50),
  can_comment  boolean     not null default true,
  can_review   boolean     not null default false,
  invited_by   uuid        not null references public.profiles (id) on delete cascade,
  expires_at   timestamptz not null,
  accepted_at  timestamptz,
  accepted_by  uuid        references public.profiles (id) on delete set null,
  revoked_at   timestamptz,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

comment on table public.helper_invitations is
  'Pending helper invitations. One row per offer; accepted/revoked rows are kept as a record.';
comment on column public.helper_invitations.email is
  'Lower-cased address the invitation was issued to. Acceptance requires the signed-in user to hold exactly this address.';
comment on column public.helper_invitations.child_ids is
  'The children this invitation grants. Copied into family_members.permissions.children on acceptance.';

create index if not exists idx_helper_invitations_family
  on public.helper_invitations (family_id, created_at desc);
create index if not exists idx_helper_invitations_email
  on public.helper_invitations (lower(email));

drop trigger if exists trg_helper_invitations_updated_at on public.helper_invitations;
create trigger trg_helper_invitations_updated_at
  before update on public.helper_invitations
  for each row execute function public.set_updated_at();

alter table public.helper_invitations enable row level security;

grant select, insert, update, delete on public.helper_invitations to authenticated;
revoke all on public.helper_invitations from anon;

-- Only the family OWNER manages invitations. Not `is_parent() and family_id =
-- current_family_id()` like the rest of 0004: inviting an adult into the family
-- is an ownership decision, and this keeps a second parent-member from quietly
-- widening the circle.
--
-- There is deliberately no policy for the invitee. They have no membership yet,
-- so no predicate could name them; redemption goes through the service role in
-- `acceptHelperInvitation`, which is also the only place the token is compared.
drop policy if exists helper_invitations_owner_all on public.helper_invitations;
create policy helper_invitations_owner_all on public.helper_invitations
  for all to authenticated
  using (
    public.is_parent()
    and family_id in (select f.id from public.families f where f.owner_id = auth.uid())
  )
  with check (
    public.is_parent()
    and family_id in (select f.id from public.families f where f.owner_id = auth.uid())
    and invited_by = auth.uid()
  );

-- =============================================================================
-- 4. profiles / family_members: a helper is not a directory
--
-- Both policies were last written in 0008, which carved siblings out for a
-- child. The same reasoning applies one step further out for a helper: the
-- grandparent invited for Nika has no business learning that Ana exists, what
-- her auth user id is, or which other adults hold which permissions.
--
-- profiles       self, the family's ADULTS (their display_name renders as the
--                author on every message and assignment_event), and the
--                profiles of the assigned children only.
-- family_members own row only. `requireParent()` reads exactly that row to
--                resolve family_id, so the app is unaffected.
--
-- The 0008 child clauses are reproduced verbatim; re-run 0008 after this file
-- and you lose the helper clauses, exactly as re-running 0004 after 0007 would.
-- =============================================================================

-- Profile ids of the children in the caller's family that the caller is NOT
-- assigned to. Empty unless the caller is a helper.
create or replace function public.helper_unassigned_child_profile_ids()
returns setof uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select c.profile_id
    from public.family_members fm
    join public.children c on c.family_id = fm.family_id
   where fm.user_id = auth.uid()
     and fm.role = 'helper'
     and c.profile_id is not null
     and c.id not in (select public.helper_child_ids());
$$;

comment on function public.helper_unassigned_child_profile_ids() is
  'Auth user ids of the children a helper is NOT assigned to. Meaningful only when the caller is a helper.';

revoke all on function public.helper_unassigned_child_profile_ids() from public;
grant execute on function public.helper_unassigned_child_profile_ids()
  to authenticated, service_role;

drop policy if exists profiles_select_self_or_family on public.profiles;
create policy profiles_select_self_or_family on public.profiles
  for select to authenticated
  using (
    id = auth.uid()
    or (
      id in (select public.my_family_user_ids())
      and (
        not public.is_child()
        or id not in (select public.sibling_profile_ids())
      )
      and (
        not public.is_helper()
        or id not in (select public.helper_unassigned_child_profile_ids())
      )
    )
  );

drop policy if exists family_members_select on public.family_members;
create policy family_members_select on public.family_members
  for select to authenticated
  using (
    user_id = auth.uid()
    or (
      not public.is_helper()
      and family_id = public.current_family_id()
      and (
        not public.is_child()
        or user_id not in (select public.sibling_profile_ids())
      )
    )
  );

-- =============================================================================
-- 5. Read policies, one per table, all keyed on helper_sees_child()
--
-- Every one is SELECT only. There is no helper INSERT/UPDATE/DELETE policy on
-- any of these tables, which is what stops a helper editing the timetable,
-- renaming a subject, inventing a lesson or retitling homework: with no policy
-- the write matches nothing and Postgres refuses it.
--
-- grades and topic_mastery appear nowhere in this file. A helper is told what
-- to supervise, not what the school thinks of the child.
-- =============================================================================
drop policy if exists subjects_helper_select on public.subjects;
create policy subjects_helper_select on public.subjects
  for select to authenticated
  using (public.helper_sees_child(child_id));

drop policy if exists schedule_slots_helper_select on public.schedule_slots;
create policy schedule_slots_helper_select on public.schedule_slots
  for select to authenticated
  using (public.helper_sees_child(child_id));

drop policy if exists lessons_helper_select on public.lessons;
create policy lessons_helper_select on public.lessons
  for select to authenticated
  using (public.helper_sees_child(child_id));

drop policy if exists topics_helper_select on public.topics;
create policy topics_helper_select on public.topics
  for select to authenticated
  using (public.helper_sees_child(public.subject_child_id(subject_id)));

drop policy if exists assignments_helper_select on public.assignments;
create policy assignments_helper_select on public.assignments
  for select to authenticated
  using (public.helper_sees_child(child_id));

drop policy if exists assignment_events_helper_select on public.assignment_events;
create policy assignment_events_helper_select on public.assignment_events
  for select to authenticated
  using (public.helper_sees_child(public.assignment_child_id(assignment_id)));

drop policy if exists attachments_helper_select on public.attachments;
create policy attachments_helper_select on public.attachments
  for select to authenticated
  using (public.helper_sees_child(child_id));

-- =============================================================================
-- 6. messages: the 0004 scaffold, narrowed
--
-- Was: any helper of the family, every child, always allowed to post.
-- Now: the assigned children only, and posting needs `can_comment`.
--
-- A helper may edit their OWN message and nothing else. There is no DELETE
-- policy for them, and none for the parent to delete a helper's message
-- individually either — `messages_parent_all` (0004) already covers the
-- parent's own moderation needs and is out of scope here.
-- =============================================================================
drop policy if exists messages_helper_select on public.messages;
create policy messages_helper_select on public.messages
  for select to authenticated
  using (public.helper_sees_child(child_id));

drop policy if exists messages_helper_insert on public.messages;
create policy messages_helper_insert on public.messages
  for insert to authenticated
  with check (
    public.helper_can_comment(child_id)
    and author_id = auth.uid()
  );

drop policy if exists messages_helper_update_own on public.messages;
create policy messages_helper_update_own on public.messages
  for update to authenticated
  using (public.helper_sees_child(child_id) and author_id = auth.uid())
  with check (public.helper_sees_child(child_id) and author_id = auth.uid());

-- 0007's `resolve_message_child_id()` already overwrites whatever child_id the
-- client sent with the one derived from the assignment, so a helper cannot post
-- into an unassigned child's thread by sending an assigned child's id: the
-- derived value is the other child's, and the WITH CHECK above then fails.

-- =============================================================================
-- 7. assignments: the review decision, and nothing else
--
-- Row scope is the policy below; column scope is the trigger in section 8.
-- Both are needed. The policy cannot say "only these columns", and the trigger
-- alone would let a helper without review rights UPDATE rows in ways the
-- trigger does not inspect.
-- =============================================================================
drop policy if exists assignments_helper_review on public.assignments;
create policy assignments_helper_review on public.assignments
  for update to authenticated
  using (public.is_helper() and public.can_review(child_id))
  with check (public.is_helper() and public.can_review(child_id));

-- =============================================================================
-- 8. assignments_status_guard(), with a helper column lock
--
-- Replaces the 0007 version wholesale. The child branch is reproduced verbatim
-- — this file must not become a way to relax it. What is new is the helper
-- branch: a reviewing helper may move the status and write `review_comment`,
-- and may not touch a single other column. Without it, `assignments_helper_review`
-- would let a helper with review rights rewrite the title, the source reference
-- or the due date of homework the parent set, which is squarely on the
-- "must never" list.
--
-- `reviewed_at` / `reviewed_by` are excluded from the lock because the
-- transition block below stamps them itself, after this check has run.
-- =============================================================================
create or replace function public.assignments_status_guard()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid           uuid    := auth.uid();
  v_service       boolean := (auth.uid() is null);
  v_child_profile uuid;
  v_is_child      boolean;
  v_is_helper     boolean;
  v_can_review    boolean;
  v_transition    text;
  v_comment       text;
begin
  select c.profile_id into v_child_profile
    from public.children c
   where c.id = new.child_id;

  v_is_child   := (v_uid is not null and v_uid is not distinct from v_child_profile);
  v_is_helper  := (not v_service) and public.is_helper();
  v_can_review := (not v_service) and public.can_review(new.child_id);

  -- ---------------------------------------------------------------- ownership
  if new.child_id is distinct from old.child_id and not v_service then
    raise exception 'assignments.child_id cannot be changed'
      using errcode = '42501';
  end if;

  -- ------------------------------------------------------- child column lock
  if v_is_child and not v_can_review then
    -- reviewer-owned columns
    if new.review_comment is distinct from old.review_comment then
      raise exception 'A child may not change review_comment' using errcode = '42501';
    end if;
    if new.reviewed_by is distinct from old.reviewed_by then
      raise exception 'A child may not change reviewed_by' using errcode = '42501';
    end if;
    if new.reviewed_at is distinct from old.reviewed_at then
      raise exception 'A child may not change reviewed_at' using errcode = '42501';
    end if;
    if new.redo_count is distinct from old.redo_count then
      raise exception 'A child may not change redo_count' using errcode = '42501';
    end if;

    -- the assignment as the parent set it. `submitted_at` is checked before the
    -- transition block below stamps it, so handing work in is still allowed.
    if new.title is distinct from old.title
       or new.description is distinct from old.description
       or new.source_ref  is distinct from old.source_ref
       or new.due_date    is distinct from old.due_date
       or new.due_time    is distinct from old.due_time
       or new.subject_id  is distinct from old.subject_id
       or new.topic_id    is distinct from old.topic_id
       or new.lesson_id   is distinct from old.lesson_id
       or new.priority    is distinct from old.priority
       or new.ai_check    is distinct from old.ai_check
       or new.created_by  is distinct from old.created_by
       or new.created_at  is distinct from old.created_at
       or new.submitted_at is distinct from old.submitted_at then
      raise exception 'A child may only change status, self_rating, difficulty_note and minutes_spent'
        using errcode = '42501';
    end if;
  end if;

  -- ------------------------------------------------------ helper column lock
  -- A helper is never the child, so this cannot collide with the branch above.
  if v_is_helper and not v_is_child then
    if new.title is distinct from old.title
       or new.description  is distinct from old.description
       or new.source_ref   is distinct from old.source_ref
       or new.due_date     is distinct from old.due_date
       or new.due_time     is distinct from old.due_time
       or new.subject_id   is distinct from old.subject_id
       or new.topic_id     is distinct from old.topic_id
       or new.lesson_id    is distinct from old.lesson_id
       or new.priority     is distinct from old.priority
       or new.ai_check     is distinct from old.ai_check
       or new.created_by   is distinct from old.created_by
       or new.created_at   is distinct from old.created_at
       or new.submitted_at is distinct from old.submitted_at
       or new.self_rating  is distinct from old.self_rating
       or new.difficulty_note is distinct from old.difficulty_note
       or new.minutes_spent   is distinct from old.minutes_spent
       or new.redo_count      is distinct from old.redo_count then
      raise exception 'A helper may only change status and review_comment'
        using errcode = '42501';
    end if;

    if not v_can_review
       and new.review_comment is distinct from old.review_comment then
      raise exception 'This helper has no review rights for this child'
        using errcode = '42501';
    end if;
  end if;

  -- -------------------------------------------------------------- transition
  if new.status is not distinct from old.status then
    return new;
  end if;

  v_transition := old.status || '->' || new.status;

  if v_transition not in (
       'assigned->in_progress',
       'assigned->submitted',
       'in_progress->submitted',
       'submitted->approved',
       'submitted->redo',
       'redo->in_progress',
       'approved->redo',
       'approved->in_progress'
     ) then
    raise exception 'Illegal assignment status transition: % -> %', old.status, new.status
      using errcode = '23514';
  end if;

  -- A helper without review rights has no business moving the status at all.
  -- The child-side transitions below belong to the child; the reviewer-side
  -- ones are already refused further down. This closes the middle: a viewing
  -- helper nudging 'assigned' to 'in_progress' on someone else's behalf.
  if v_is_helper and not v_can_review then
    raise exception 'This helper has no review rights for this child'
      using errcode = '42501';
  end if;

  -- corrections out of an already approved assignment are reviewer-only
  if old.status = 'approved' and not (v_can_review or v_service) then
    raise exception 'Only a parent (or a helper with review rights) may reopen an approved assignment'
      using errcode = '42501';
  end if;

  -- approve / return for redo are reviewer-only
  if new.status in ('approved', 'redo') then
    if not (v_can_review or v_service) then
      raise exception 'Only a parent (or a helper with review rights) may set status to %', new.status
        using errcode = '42501';
    end if;
    new.reviewed_at := now();
    new.reviewed_by := v_uid;
  end if;

  if new.status = 'submitted' then
    new.submitted_at := now();
  end if;

  if old.status = 'redo' and new.status = 'in_progress' then
    new.redo_count := coalesce(old.redo_count, 0) + 1;
  end if;

  -- ------------------------------------------------------------------ audit
  -- On a review decision always record the comment that was in force, even when it
  -- repeats the previous one. Returning the same work twice with the same wording is
  -- exactly the case the audit trail exists to show; de-duplicating it would hide
  -- the second rejection.
  v_comment := case
                 when new.status in ('approved', 'redo')
                   then new.review_comment
                 when new.review_comment is distinct from old.review_comment
                   then new.review_comment
                 else null
               end;

  insert into public.assignment_events
    (assignment_id, actor_id, from_status, to_status, comment)
  values
    (new.id, v_uid, old.status, new.status, v_comment);

  return new;
end;
$$;

drop trigger if exists trg_assignments_status_guard on public.assignments;
create trigger trg_assignments_status_guard
  before update on public.assignments
  for each row execute function public.assignments_status_guard();

-- =============================================================================
-- 9. Storage: look, do not touch
--
-- 0005 gave a helper SELECT on `{any child of the family}/...`. Narrow it to the
-- assigned children. There is still no helper INSERT/UPDATE/DELETE policy on
-- storage.objects, so evidence cannot be planted or quietly removed by someone
-- who is not responsible for the child.
-- =============================================================================
drop policy if exists evidence_helper_select on storage.objects;
create policy evidence_helper_select on storage.objects
  for select to authenticated
  using (
    bucket_id = 'evidence'
    and public.helper_sees_child(public.storage_child_id(name))
  );

-- =============================================================================
-- 10. Why a helper cannot be used to reopen 0007 or 0008
--
-- 0007 (profiles.role not self-writable): the fix is a column-level REVOKE on
--   `authenticated` plus `trg_profiles_guard_identity`. Both are role-wide and
--   this file grants nothing back, so a helper hits the same
--   "permission denied for table profiles" a child does. A helper therefore
--   cannot promote themselves to parent and inherit `is_parent()`.
--
-- 0008 (a child cannot enumerate a sibling): untouched — the child clauses in
--   section 4 are the 0008 text, and every new predicate in this file starts
--   from `is_helper()`, which is false for a child. The reverse direction is
--   new and handled: section 4 also hides the unassigned children from the
--   helper, so the promise "you were invited for Nika" does not leak Ana.
--
-- Escalation paths a helper might try, and what stops them:
--   widen their own permissions   family_members has no helper UPDATE policy;
--                                 `family_members_update_parent` needs
--                                 is_parent() AND ownership of the family.
--   invite another helper         `helper_invitations_owner_all` needs
--                                 is_parent() AND ownership.
--   create their own family and   `families_insert_parent` needs is_parent().
--     become its parent
--   read the child's invite_code  no policy on public.children for a helper at
--     and take over the account   all; `helper_children` does not select the
--                                 column.
--   approve for an unassigned     `can_review()` requires the id to be in the
--     child                       explicit array of a non-revoked membership.
--   keep access after removal     every function in section 1 filters on
--                                 `revoked_at is null`, and they are STABLE,
--                                 i.e. re-evaluated per statement.
-- =============================================================================

-- ---------------------------------------------------------------------
-- 0011_notify_parent_on_helper_review.sql
-- ---------------------------------------------------------------------
-- 0011_notify_parent_on_helper_review.sql
--
-- A helper with review rights (0010) can close the whole loop with no parent in
-- it: the tutor approves, the child moves on, and the parent finds out never.
-- `assignments.reviewed_by` records who decided, but nothing surfaces it, and a
-- parent who delegated "can review" to a grandmother did not thereby agree to
-- stop knowing what happened to their child's homework.
--
-- So: when the reviewer is not a parent of the family, the parents are told too.
-- The child's own notification is unchanged.
--
-- This replaces `notify_assignment_status()` from 0009. Everything up to the
-- approved/redo branch is carried over verbatim.

create or replace function public.notify_assignment_status()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor        uuid := auth.uid();
  v_child_name   text;
  v_family_id    uuid;
  v_child_user   uuid;
  v_subject      text;
  v_payload      jsonb;
  v_recipient    uuid;
  v_actor_name   text;
  v_actor_parent boolean;
begin
  if new.status is not distinct from old.status then
    return null;
  end if;

  if new.status not in ('submitted', 'approved', 'redo') then
    return null;
  end if;

  select c.name, c.family_id, c.profile_id
    into v_child_name, v_family_id, v_child_user
    from public.children c
   where c.id = new.child_id;

  if v_family_id is null then
    return null;
  end if;

  select s.name into v_subject
    from public.subjects s
   where s.id = new.subject_id;

  if new.status = 'submitted' then
    v_payload := jsonb_build_object(
      'v',            1,
      'audience',     'parent',
      'count',        1,
      'assignment_id', new.id,
      'child_id',     new.child_id,
      'child_name',   v_child_name,
      'subject_name', v_subject,
      'title',        left(new.title, 120)
    );

    for v_recipient in
      select u from public.family_parent_ids(v_family_id) as u
    loop
      if v_recipient is distinct from v_actor then
        perform public.enqueue_notification(v_recipient, 'assignment_submitted', v_payload);
      end if;
    end loop;

    return null;
  end if;

  -- approved | redo -> the child whose work it is
  if v_child_user is not null and v_child_user is distinct from v_actor then
    v_payload := jsonb_build_object(
      'v',            1,
      'audience',     'child',
      'count',        1,
      'assignment_id', new.id,
      'child_id',     new.child_id,
      'child_name',   v_child_name,
      'subject_name', v_subject,
      'title',        left(new.title, 120),
      'preview',      nullif(left(coalesce(new.review_comment, ''), 120), '')
    );

    perform public.enqueue_notification(
      v_child_user,
      case when new.status = 'approved' then 'assignment_approved' else 'assignment_redo' end,
      v_payload
    );
  end if;

  -- ... and the parents, when somebody other than a parent decided.
  --
  -- `family_parent_ids()` is the definition of "a parent of this family", so
  -- membership in it is the test — not `profiles.role`, which a helper in one
  -- family could hold as a parent of another. A null actor is the service role
  -- (seed, admin script) and is treated as privileged, matching 0003.
  if v_actor is null then
    return null;
  end if;

  select exists (
    select 1 from public.family_parent_ids(v_family_id) as u where u = v_actor
  ) into v_actor_parent;

  if v_actor_parent then
    return null;
  end if;

  select p.display_name into v_actor_name
    from public.profiles p
   where p.id = v_actor;

  v_payload := jsonb_build_object(
    'v',            1,
    'audience',     'parent',
    'count',        1,
    'assignment_id', new.id,
    'child_id',     new.child_id,
    'child_name',   v_child_name,
    'subject_name', v_subject,
    'title',        left(new.title, 120),
    'actor_name',   v_actor_name,
    'preview',      nullif(left(coalesce(new.review_comment, ''), 120), '')
  );

  for v_recipient in
    select u from public.family_parent_ids(v_family_id) as u
  loop
    perform public.enqueue_notification(
      v_recipient,
      case when new.status = 'approved'
             then 'assignment_approved_by_helper'
           else 'assignment_redo_by_helper'
      end,
      v_payload
    );
  end loop;

  return null;
end;
$$;

comment on function public.notify_assignment_status() is
  'Notifies on submit/approve/redo. When a non-parent (a helper with review '
  'rights) decides, the parents are notified as well as the child.';

-- ---------------------------------------------------------------------
-- 0012_child_assignment_insert.sql
-- ---------------------------------------------------------------------
-- =============================================================================
-- SCHOOL-HUB — 0012_child_assignment_insert.sql
-- Makes `assignments_insert_own` safe now that a child-facing create screen
-- actually uses it. No schema change, so `src/lib/db.types.ts` is unaffected.
-- Depends on: 0003_functions.sql (the lookup helpers), 0004_rls.sql
--
-- WHY
-- SPEC section 3.1 has the child record, per lesson, what homework was given
-- and photograph the book page. Until now the only create path was
-- `createAssignmentAction`, which is `requireParent()`, so nothing inserted
-- through `assignments_insert_own` and its gap never mattered.
--
-- THE GAP
-- The 0004 policy pins the row's own identity — `child_id = my_child_id()`,
-- `status = 'assigned'`, no review fields — but says nothing about the three
-- foreign keys the row points AT. A child could therefore post
--
--     insert into public.assignments (child_id, title, lesson_id)
--     values (<my child id>, 'x', <SIBLING's lesson id>);
--
-- and the row passes: it is their own assignment, in the right state, merely
-- hanging off their sibling's lesson / subject / topic. The damage is not a
-- read (RLS still hides the sibling's row from them) but a write into shared
-- structure: the sibling's lesson card starts counting an assignment that is
-- not theirs, the parent's per-subject filters and redo-rate-by-subject report
-- attribute the child's work to the wrong child's subject, and a child could
-- quietly graft their own homework onto a sibling's timetable.
--
-- THE FIX
-- Each foreign key, when not null, must resolve back to the same child. The
-- three `security definer` lookups from 0003 already express exactly that and
-- are reused verbatim rather than inlining joins into the policy — a policy
-- body runs as the caller, so a hand-written `select ... from public.subjects`
-- inside it would be filtered by `subjects_select_own` and silently evaluate
-- to null (i.e. NOT NULL = false, "reject everything") the moment the subject
-- is a sibling's. The helpers are `security definer`, so they see the real row
-- and the comparison is the one intended.
--
-- `public.topic_child_id()` already walks topics -> subjects, which is how a
-- topic is child-scoped (SPEC section 2: `topics` carries only `subject_id`).
--
-- NOT CHANGED HERE
-- The column lock in 0007 section 3 is a BEFORE UPDATE trigger and is not
-- involved in an INSERT; the initial state of a child-created row is pinned by
-- this policy instead (`status = 'assigned'`, no `review_comment`, no
-- `reviewed_by` / `reviewed_at`, `redo_count = 0`). Both halves are asserted in
-- supabase/test/rls.test.mjs block 24.
-- =============================================================================

drop policy if exists assignments_insert_own on public.assignments;
create policy assignments_insert_own on public.assignments
  for insert to authenticated
  with check (
    -- ---------------------------------------------------- the row itself
    child_id = public.my_child_id()
    and status = 'assigned'
    and redo_count = 0
    and reviewed_by is null
    and reviewed_at is null
    and review_comment is null

    -- ------------------------------------------- what the row points at
    -- Null is allowed: homework that belongs to no lesson, no subject and no
    -- topic is legitimate (the "+" on /kid/assignments). A value that IS given
    -- must be the child's own.
    and (
      subject_id is null
      or public.subject_child_id(subject_id) = public.my_child_id()
    )
    and (
      topic_id is null
      or public.topic_child_id(topic_id) = public.my_child_id()
    )
    and (
      lesson_id is null
      or public.lesson_child_id(lesson_id) = public.my_child_id()
    )
  );

comment on policy assignments_insert_own on public.assignments is
  'A child may add homework they were given, in the initial state only, and only '
  'hanging off their own lesson / subject / topic (0012).';

commit;
